let CURRENT_TAB = 'exec';
let FC = [];           // filtered practices

/** Test/demo billing practices — excluded from portfolio KPIs & aggregate charts (still searchable). */
const BPN_EXCLUDE_FROM_KPI = new Set([111, 112, 9876543, 1230000]);
function isExcludedKpiBpn(bpn){ return BPN_EXCLUDE_FROM_KPI.has(Number(bpn)); }
function fcForKpiStats(){ return FC.filter(p => !isExcludedKpiBpn(p.bpn)); }
function countEligiblePractices(){
  return DATA.practices.filter(p => !isExcludedKpiBpn(p.bpn)).length;
}
/** Sum bpnDaily rows for one date index, excluding test BPNs (portfolio KPI charts). */
function aggregateBpnDailyAtDateIdx(di){
  let enc = 0, encUsers = 0, featUsers = 0;
  let evClin = 0, evScripts = 0, evPath = 0, evAI = 0, evPrev = 0, evTask = 0, evCust = 0;
  const bd = DATA.bpnDaily;
  if (!bd) return null;
  for (const k of Object.keys(bd)){
    if (isExcludedKpiBpn(k)) continue;
    const recs = bd[k];
    let lo = 0, hi = recs.length - 1, found = null;
    while (lo <= hi){
      const mid = (lo + hi) >> 1;
      if (recs[mid][0] < di) lo = mid + 1;
      else if (recs[mid][0] > di) hi = mid - 1;
      else { found = recs[mid]; break; }
    }
    if (!found) continue;
    const r = found;
    enc += r[1];
    evClin += r[3]; evScripts += r[4]; evPath += r[5]; evAI += r[6];
    evPrev += r[7]; evTask += r[8]; evCust += r[9];
    encUsers += r[11]; featUsers += r[12];
  }
  const dstr = SLICER && SLICER.dates && SLICER.dates[di] ? SLICER.dates[di] : '';
  return {
    d: dstr, date: dstr,
    encUsers, featUsers,
    enc, evEnc: enc,
    evClin, evScripts, evPath, evAI, evPrev, evTask, evCust,
  };
}
/** Daily series for KPI charts — excludes test practices (see dailyForSlice for raw totals). */
function dailyForSliceKpi(){
  const out = [];
  if (!SLICER || !SLICER.dates || SLICER.endIdx < SLICER.startIdx) return out;
  for (let i = SLICER.startIdx; i <= SLICER.endIdx; i++){
    const row = aggregateBpnDailyAtDateIdx(i);
    if (row) out.push(row);
  }
  return out;
}

const charts = {};     // chart.js instances
let SELECTED_FEAT_CATS = ['1. Encounters','2. Clinical Doc','3. Scripts','5. AI Features'];

/** Single shared login — data refresh is via generate_dashboard_data.py (not this UI). */
const DASHBOARD_PASSWORD = 'HbC@BC2026';
const SESSION_KEY = 'hbc_dashboard_ok';

/* ============================================================
   Auth flow
   ============================================================ */
function doLogin(){
  const pwd = document.getElementById('auth-pwd').value;
  if (pwd !== DASHBOARD_PASSWORD){
    document.getElementById('auth-error').style.display = 'block';
    document.getElementById('auth-pwd').value = '';
    return;
  }
  sessionStorage.setItem(SESSION_KEY, '1');
  enterApp();
}
function signOut(){
  sessionStorage.removeItem(SESSION_KEY);
  location.reload();
}
function enterApp(){
  document.getElementById('user-name').textContent = 'BC Client Tracker';
  document.getElementById('user-role').textContent = 'Dashboard';
  document.getElementById('user-avatar').textContent = 'HB';

  document.getElementById('auth-gate').style.display = 'none';
  document.getElementById('app').style.display = 'flex';
  document.body.style.overflow = '';
  const _stale = document.getElementById('provider-modal');
  if (_stale) _stale.remove();
  window._openModalKey = null;

  document.getElementById('data-period').textContent = formatDate(DATA.stats.dataPeriodEnd);

  const _lr = document.getElementById('hdr-last-refresh');
  if (_lr) {
    const m = DATA.metadata || {};
    if (m.LastRefreshed_SAST) _lr.textContent = m.LastRefreshed_SAST;
    else if (m.LastRefreshed) {
      const d = new Date(m.LastRefreshed);
      _lr.textContent = isNaN(d.getTime()) ? String(m.LastRefreshed) : d.toLocaleString('en-ZA', { dateStyle: 'medium', timeStyle: 'short' });
    } else if (DATA.generatedAt) {
      const d = new Date(DATA.generatedAt);
      _lr.textContent = isNaN(d.getTime()) ? String(DATA.generatedAt) : d.toLocaleString('en-ZA', { dateStyle: 'medium', timeStyle: 'short' });
    } else _lr.textContent = '—';
  }

  populateFilters();
  applyFilters();
  renderExec();
  renderDefs();
}

/* ============================================================
   Helpers
   ============================================================ */
function fmt(n){
  if (n === null || n === undefined || isNaN(n)) return '—';
  if (typeof n !== 'number') n = Number(n);
  if (n >= 1_000_000) return (n/1_000_000).toFixed(1).replace(/\.0$/,'') + 'M';
  if (n >= 1_000) return (n/1_000).toFixed(1).replace(/\.0$/,'') + 'k';
  return n.toLocaleString();
}
function fmtFull(n){
  if (n === null || n === undefined || isNaN(n)) return '—';
  return Number(n).toLocaleString();
}
function pct(n,d){
  if (!d) return '0%';
  return Math.round(100*n/d) + '%';
}
function pct1(n,d){
  if (!d) return '0';
  return (100*n/d).toFixed(1).replace(/\.0$/,'');
}

/**
 * Trailing window (up to 30 days) within the current date slicer, ending on the slicer end date.
 * Executive engagement uses recent daily provDaily, not lifetime pr.enc / pr.feat.
 */
function getExec30dWindow(){
  if (!SLICER || !SLICER.dates || !SLICER.dates.length) {
    return { fromIdx: 0, toIdx: 0, nDays: 0, startStr: '', endStr: '' };
  }
  const a = SLICER.startIdx, b = SLICER.endIdx;
  const to = b;
  const from = Math.max(a, b - 29);
  return {
    fromIdx: from,
    toIdx: to,
    nDays: to - from + 1,
    startStr: SLICER.dates[from],
    endStr: SLICER.dates[to],
  };
}

/** consult-complete (enc) and meaningful feature total (feat) in the executive window, from provDaily. */
function provider30dEncFeatFromDaily(provKey){
  const w = getExec30dWindow();
  if (!w.nDays) return { enc: 0, feat: 0 };
  const recs = (DATA.provDaily && provKey && DATA.provDaily[provKey]) || [];
  let enc = 0, feat = 0;
  for (const r of recs){
    if (r[0] < w.fromIdx || r[0] > w.toIdx) continue;
    enc += (r[1] || 0);
    feat += (r[2] || 0);
  }
  return { enc, feat };
}

/** Classify each treating provider by enc/feat in the executive window (provDaily). */
function providerEngagementSplit(practices){
  let encProv = 0, featProv = 0, noneProv = 0;
  for (const p of practices){
    for (const pr of (p.providers || [])){
      const { enc, feat } = provider30dEncFeatFromDaily(pr.provKey);
      if (enc > 0) encProv++;
      else if (feat > 0) featProv++;
      else noneProv++;
    }
  }
  return { encProv, featProv, noneProv };
}

/** Meaningful feature-event sum in the exec window for providers active there (≥1 consult-complete or ≥1 feature event). */
function sumFeatEventsActiveProviders(practices){
  let sum = 0;
  for (const p of practices){
    for (const pr of (p.providers || [])){
      const { enc, feat } = provider30dEncFeatFromDaily(pr.provKey);
      if (enc > 0 || feat > 0) sum += feat;
    }
  }
  return sum;
}

/** Unified KPI counts — activity window is trailing up to 30d within the date slicer (provDaily). */
function kpiBundleForFilteredPractices(set){
  const sp = providerEngagementSplit(set);
  const encProv = sp.encProv, featProv = sp.featProv, noneProv = sp.noneProv;
  const activeProv = encProv + featProv;
  const roster = encProv + featProv + noneProv;
  const sumFeatActive = sumFeatEventsActiveProviders(set);
  const featPerActive = activeProv ? (sumFeatActive / activeProv) : 0;
  return {
    pracN: set.length,
    encProv, featProv, noneProv, activeProv, roster,
    sumFeatActive, featPerActive,
  };
}

/** Subtitle for Active treating providers KPIs (trailing ≤30d activity window in slicer, provDaily). */
function getActiveProvidersKpiSubtitle(){
  const w = getExec30dWindow();
  if (!w.nDays) return 'Set date range for activity window';
  const winBit = w.nDays < 30
    ? (w.nDays + 'd · ' + formatDateShort(w.startStr) + '–' + formatDateShort(w.endStr))
    : ('up to 30d ending ' + formatDateShort(w.endStr));
  return '≥1 consult-complete or feature · ' + winBit;
}
function formatDate(s){
  if (!s) return '—';
  const d = new Date(s);
  if (isNaN(d)) return s;
  return d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
}
function formatDateShort(s){
  if (!s) return '—';
  const d = new Date(s);
  if (isNaN(d)) return s;
  return d.toLocaleDateString('en-GB',{day:'numeric',month:'short'});
}
function escapeHtml(s){
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}
/** For HTML attribute values (e.g. data-prov-key). */
function escapeHtmlAttr(s){
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/&/g,'&amp;').replace(/"/g,'&quot;')
    .replace(/'/g,'&#39;').replace(/</g,'&lt;');
}

function openProviderFeaturesFromBtn(btn){
  const k = btn.getAttribute('data-prov-key');
  if (k !== null && k !== '') openProviderFeatures(k);
}

function providerHasActivityInSlicerWindow(pr){
  if (!SLICER || !SLICER.dates || !SLICER.dates.length) return true;
  if (typeof slicerIsFullRange === 'function' && slicerIsFullRange()) return true;
  const recs = (DATA.provDaily && pr.provKey && DATA.provDaily[pr.provKey]) || [];
  for (let i = 0; i < recs.length; i++){
    const r = recs[i];
    if (r[0] < SLICER.startIdx || r[0] > SLICER.endIdx) continue;
    const feat = r[2] || 0, noise = r[10] || 0;
    if (feat > 0 || noise > 0) return true;
  }
  return false;
}

function providersForTablePanel(p){
  const all = p.providers || [];
  const roster = all.length;
  if (!SLICER || !SLICER.dates || !SLICER.dates.length || (typeof slicerIsFullRange === 'function' && slicerIsFullRange())){
    return { list: all, shown: roster, roster };
  }
  const list = all.filter(providerHasActivityInSlicerWindow);
  return { list, shown: list.length, roster };
}

function encounterTableProviderCountHtml(p){
  const { shown, roster } = providersForTablePanel(p);
  if (!SLICER || !SLICER.dates || !SLICER.dates.length || (typeof slicerIsFullRange === 'function' && slicerIsFullRange())){
    return String(roster);
  }
  return `${shown}<span style="font-size:10px;color:var(--slate-600);font-variant-numeric:tabular-nums"> / ${roster}</span>`;
}

function bcViewProviderCountHtml(p){
  const { shown, roster } = providersForTablePanel(p);
  if (!SLICER || !SLICER.dates || !SLICER.dates.length || (typeof slicerIsFullRange === 'function' && slicerIsFullRange())){
    return `<strong style="color:var(--brand-purple);font-variant-numeric:tabular-nums">${roster}</strong>`;
  }
  return `<strong style="color:var(--brand-purple);font-variant-numeric:tabular-nums">${shown}</strong><span style="font-size:10px;color:var(--slate-600);font-variant-numeric:tabular-nums"> / ${roster}</span>`;
}

function statusBadge(s){
  const STATUS_TIPS = {
    'Active':               'Practice is live and actively using the platform',
    'In Progress':          'Onboarding or implementation currently in progress',
    'Inactive':             'Practice is not currently active on the platform',
    'Paused':               'Temporarily paused — not in active use',
    'On Hold':              'On hold — pending a decision or action',
    'Cancelled':            'Contract or agreement has been cancelled',
    'Pending Cancellation': 'Cancellation request submitted, awaiting processing',
    'Rejected':             'Application or request was rejected',
  };
  const cls = ({
    'Active':'b-active', 'In Progress':'b-progress', 'Inactive':'b-inactive',
    'Paused':'b-paused', 'On Hold':'b-paused', 'Cancelled':'b-cancel',
    'Pending Cancellation':'b-cancel', 'Rejected':'b-rejected'
  })[s] || 'b-unknown';
  const tip = STATUS_TIPS[s] || 'Unknown status';
  return `<span class="badge ${cls}" title="${escapeHtml(tip)}">${escapeHtml(s||'Unknown')}</span>`;
}
function pmaBadge(p){
  return p === 'Nova'
    ? '<span class="badge b-pma-nova" title="Nova — modern cloud-based PMA platform">Nova</span>'
    : '<span class="badge b-pma-mps" title="myMPS — standard PMA platform">myMPS</span>';
}
const PERSONA_DEFS = {
  'Power Clinical User':   { cls: 'b-power',     tip: 'Active ≥20 days in a 30-day period with completed encounters' },
  'Active Clinical User':  { cls: 'b-standard',  tip: 'Active ≥10 days in a 30-day period with completed encounters' },
  'Low Clinical User':     { cls: 'b-casual',    tip: 'Active ≥5 days in a 30-day period with completed encounters' },
  'Feature-Only User':     { cls: 'b-admin',     tip: 'Has feature & noise events but zero completed encounters' },
  'Admin / Power Support': { cls: 'b-admin',     tip: 'Feature-heavy usage (>300 events) with no/minimal encounters' },
  'Standard Clinical User':{ cls: 'b-standard',  tip: 'Legacy label — now Active Clinical User' },
  'Casual User':           { cls: 'b-casual',    tip: 'Legacy label — now Low Clinical User' },
  'Light Clinical User':   { cls: 'b-casual',    tip: 'Legacy label — now Low Clinical User' },
  'Inactive':              { cls: 'b-inactive-p',tip: 'Contract status is not Active' },
  'Dormant':               { cls: 'b-inactive-p',tip: 'No events recorded in the selected date window' },
};
function personaBadge(p){
  const def = PERSONA_DEFS[p] || { cls: 'b-casual', tip: p };
  return `<span class="badge ${def.cls}" title="${escapeHtml(def.tip)}">${escapeHtml(p)}</span>`;
}
function engagementBadge(e){
  if (e === 'encounter')    return '<span class="badge b-eng-enc"  title="At least one consult-complete event in the selected window">Encounter</span>';
  if (e === 'feature_only') return '<span class="badge b-eng-feat" title="Used platform features but no consult-complete events recorded">Feature-only</span>';
  return '<span class="badge b-eng-inactive" title="No events of any kind recorded in the selected date window">No activity</span>';
}
/** Compare displayed version to metadata latest (embedded onLatest can lag after bundle edits). */
function versionMatchesLatest(v, latest, on){
  if (!v) return false;
  const lv = (latest || '').trim();
  return Boolean(on) || (Boolean(lv) && String(v).trim() === lv);
}
function versionChip(v, latest, on){
  if (!v) return '<span class="badge b-ver-none">—</span>';
  if (versionMatchesLatest(v, latest, on)) return `<span class="badge b-ver-ok">${escapeHtml(v)} ✓</span>`;
  return `<span class="badge b-ver-old">${escapeHtml(v)}</span>`;
}
function practiceMatchesLatestMeta(p){
  return versionMatchesLatest(p.appVer, DATA.metadata.LatestVersion, p.onLatest);
}
function severityBadge(s){
  const map = {cr:'Critical', wa:'Warning', in:'Info'};
  const cls = `b-sev-${s}`;
  return `<span class="badge ${cls}">${map[s]||s}</span>`;
}

/* Friendly feature labels — converts raw event keys to human-readable */
const FEATURE_LABELS = {
  'consult-complete': 'Consult complete',
  'consult-quick-note': 'Quick note',
  'consult-plan-created': 'Plan created',
  'patient-file-talking-points-updated': 'Talking points updated',
  'sidebar-encounter-summary-opened': 'Encounter summary opened',
  'AlgoliaSearch-Medicine-Search': 'Medicine search',
  'smart-generic-medicine-selected': 'Generic medicine selected',
  'timeline-quick-note-added': 'Timeline quick note',
  'patient-card-opened': 'Patient card opened',
  'consult-started': 'Consult started',
  'medication-script-saved': 'Script saved',
  'medication-script-printed': 'Script printed',
  'icd10-code-added': 'ICD-10 added',
  'pathology-form-opened': 'Pathology form opened',
  'pathology-test-selected': 'Pathology test selected',
  'pathology-form-submitted': 'Pathology form submitted',
  'patient-search-performed': 'Patient search',
  'patient-created': 'Patient created',
  'appointment-created': 'Appointment created',
  'appointment-checked-in': 'Appointment checked in',
  'task-created': 'Task created',
  'task-completed': 'Task completed',
  'reminder-set': 'Reminder set',
  'ai-summary-generated': 'AI summary generated',
  'ai-clinical-assistant-opened': 'AI Assistant opened',
  'ai-prompt-submitted': 'AI prompt submitted',
  'ai-suggestion-accepted': 'AI suggestion accepted',
  'preventative-care-screening': 'Preventative screening',
  'vaccination-recorded': 'Vaccination recorded',
  'sidebar-opened': 'Sidebar opened',
  'preferences-saved': 'Preferences saved',
};
function featLabel(raw){
  if (!raw) return '';
  if (FEATURE_LABELS[raw]) return FEATURE_LABELS[raw];
  // Fallback: humanise dash-cased keys
  return raw.replace(/-/g,' ').replace(/_/g,' ')
    .replace(/\b\w/g,c => c.toUpperCase());
}

/* Tab switching */
function switchTab(name, el){
  CURRENT_TAB = name;
  document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');
  document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
  document.getElementById('s-'+name).classList.add('active');
  // Refresh chart sizing on visible section
  setTimeout(() => {
    Object.values(charts).forEach(c => { try { c.resize(); } catch(e){} });
  }, 50);
  // Render section
  if (name === 'exec') renderExec();
  else if (name === 'overview') renderOverview();
  else if (name === 'encounters') renderEncounters();
  else if (name === 'features') renderFeatures();
  else if (name === 'bcview') renderBCView();
  else if (name === 'anomalies') renderAnomalies();
  else if (name === 'defs') renderDefs();
}

/* ============================================================
   Filters
   ============================================================ */
function populateFilters(){
  const bcSel = document.getElementById('f-bc');
  DATA.lists.bcs.forEach(b => {
    const opt = document.createElement('option');
    opt.value = b; opt.textContent = b;
    bcSel.appendChild(opt);
  });
  const teamSel = document.getElementById('f-team');
  const encTeamSel = document.getElementById('enc-team-filter');
  DATA.lists.teams.forEach(t => {
    const o1 = document.createElement('option');
    o1.value = t; o1.textContent = t;
    teamSel.appendChild(o1);
    const o2 = o1.cloneNode(true);
    encTeamSel.appendChild(o2);
  });
}

function applyFilters(){
  const bc = document.getElementById('f-bc').value;
  const team = document.getElementById('f-team').value;
  const pma = document.getElementById('f-pma').value;
  const eng = document.getElementById('f-eng').value;
  const q = document.getElementById('f-q').value.trim().toLowerCase();

  const _sliced = aggregateAllForSlice();
  FC = _sliced.filter(p => {
    if (bc && p.bc !== bc) return false;
    if (team && p.team !== team) return false;
    if (pma && p.pma !== pma) return false;
    if (eng && p.engagement !== eng) return false;
    if (q){
      const hay = [
        p.name, p.bpn, p.bc, p.team, p.speciality, p.appVer,
        ...((p.providers||[]).flatMap(pr => [pr.name, pr.tpn]))
      ].join(' ').toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  // Update result count
  const all = DATA.practices.length;
  const txt = FC.length === all
    ? `Showing all <strong>${fmtFull(all)}</strong> clients`
    : `Showing <strong>${fmtFull(FC.length)}</strong> of ${fmtFull(all)} clients`;
  document.getElementById('filter-result').innerHTML = txt;

  // Re-render current tab
  if (CURRENT_TAB === 'exec') renderExec();
  else if (CURRENT_TAB === 'overview') renderOverview();
  else if (CURRENT_TAB === 'encounters') renderEncounters();
  else if (CURRENT_TAB === 'features') renderFeatures();
  else if (CURRENT_TAB === 'bcview') renderBCView();
  else if (CURRENT_TAB === 'anomalies') renderAnomalies();
  // defs tab is static — no data-driven re-render needed

  // Update anomaly tab badge based on filtered set
  const anomCount = computeAnomCounts(fcForKpiStats()).total;
  document.getElementById('anom-tab-count').textContent = anomCount;
  updateSlicerDependentLabels();
}

function clearFilters(){
  document.getElementById('f-bc').value = '';
  document.getElementById('f-team').value = '';
  document.getElementById('f-pma').value = '';
  document.getElementById('f-eng').value = '';
  document.getElementById('f-q').value = '';
  applyFilters();
}

/* ============================================================
   Anomaly counts (re-computed for filtered set)
   ============================================================ */
function computeAnomCounts(set){
  let noBc = 0, noEnc = 0, oldVer = 0;
  for (const p of set){
    if (!p.bc && (p.enc > 0 || p.feat > 0)) noBc++;
    else if (p.status === 'Active' && p.bc && p.enc === 0 && p.feat > 100) noEnc++;
    else if (p.enc > 100 && p.appVer && !practiceMatchesLatestMeta(p)) oldVer++;
  }
  return { noBc, noEnc, oldVer, total: noBc + noEnc + oldVer };
}

/* ============================================================
   Chart helpers
   ============================================================ */
function getCss(name){
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}
const CHART_FONT = "Figtree, system-ui, sans-serif";
function applyChartDefaults(){
  if (!window.Chart) return;
  Chart.defaults.font.family = CHART_FONT;
  Chart.defaults.font.size = 11;
  Chart.defaults.color = getCss('--slate-700');
  Chart.defaults.plugins.legend.labels.usePointStyle = true;
  Chart.defaults.plugins.legend.labels.boxWidth = 8;
  Chart.defaults.plugins.legend.labels.padding = 12;
  Chart.defaults.plugins.tooltip.backgroundColor = getCss('--slate-900');
  Chart.defaults.plugins.tooltip.titleColor = '#fff';
  Chart.defaults.plugins.tooltip.bodyColor = '#fff';
  Chart.defaults.plugins.tooltip.padding = 10;
  Chart.defaults.plugins.tooltip.cornerRadius = 6;
  Chart.defaults.plugins.tooltip.boxPadding = 4;
}

function killChart(id){ if (charts[id]){ charts[id].destroy(); delete charts[id]; } }

/* ============================================================
   EXECUTIVE SUMMARY
   ============================================================ */
function renderExec(){
  applyChartDefaults();
  const set = FC;
  const kpiSet = fcForKpiStats();
  const kb = kpiBundleForFilteredPractices(kpiSet);
  const pracN = kb.pracN;
  const enc = kb.encProv, feat = kb.featProv, none = kb.noneProv;
  const activeProv = kb.activeProv;
  const provTotal = kb.roster;
  let noBcProv = 0;
  for (const p of kpiSet){
    if (!p.bc) noBcProv += (p.providers || []).length;
  }

  const wExec = getExec30dWindow();
  const winSub = wExec.nDays
    ? (wExec.nDays < 30
        ? ('Activity lookback: ' + formatDateShort(wExec.startStr) + '–' + formatDateShort(wExec.endStr) + ' (' + wExec.nDays + 'd, full range)')
        : ('Activity lookback: ' + formatDateShort(wExec.startStr) + '–' + formatDateShort(wExec.endStr) + ' (trailing 30d in range)'))
    : 'Set a date range in the slicer for 30d activity';
  const eligiblePrac = countEligiblePractices();
  const pracSub = FC.length === DATA.practices.length && kb.pracN === eligiblePrac
    ? (fmtFull(pracN) + ' billing practices')
    : (fmtFull(pracN) + ' practices in filter');

  document.getElementById('ek-prac').textContent = fmtFull(pracN);
  document.getElementById('ek-prac-sub').textContent = pracSub + ' · ' + winSub;
  document.getElementById('ek-roster').textContent = fmtFull(provTotal);
  document.getElementById('ek-roster-sub').textContent = 'active + inactive in filter';
  document.getElementById('ek-active').textContent = fmtFull(activeProv);
  document.getElementById('ek-active-sub').textContent = getActiveProvidersKpiSubtitle();
  document.getElementById('ek-inactive').textContent = fmtFull(none);
  document.getElementById('ek-inactive-sub').textContent = provTotal ? (pct(none, provTotal) + ' of roster (treating providers)') : '0%';
  document.getElementById('ek-favg').textContent = activeProv
    ? (kb.featPerActive >= 10 ? kb.featPerActive.toFixed(1) : kb.featPerActive.toFixed(2))
    : '—';
  document.getElementById('ek-favg-sub').textContent = activeProv
    ? 'mean feature events · active providers only'
    : 'no active providers in window';

  const elActiveKpi = document.getElementById('ek-active-kpi');
  if (elActiveKpi) {
    elActiveKpi.title = wExec.nDays
      ? ('Active = encounter (' + fmtFull(enc) + ') + feature-only (' + fmtFull(feat) + ') = ' + fmtFull(activeProv) +
         ' in ' + wExec.nDays + 'd ending ' + formatDate(wExec.endStr) + '. Inactive = ' + fmtFull(none) + ' on roster.')
      : 'Set the date slicer to compute the activity window.';
  }

  document.getElementById('ek-enc').textContent = fmtFull(enc);
  document.getElementById('ek-enc-sub').textContent = activeProv
    ? (pct(enc, activeProv) + ' of active · ' + pct(enc, provTotal) + ' of roster')
    : '0%';
  document.getElementById('ek-feat').textContent = fmtFull(feat);
  document.getElementById('ek-feat-sub').textContent = activeProv
    ? (pct(feat, activeProv) + ' of active (feature-only)')
    : '0%';
  document.getElementById('ek-nobc').textContent = fmtFull(noBcProv);
  // Engagement bar: share of treating providers
  const encPct = provTotal ? (100*enc/provTotal) : 0;
  const featPct = provTotal ? (100*feat/provTotal) : 0;
  const nonePct = provTotal ? (100*none/provTotal) : 0;
  document.getElementById('bar-enc').style.width = encPct + '%';
  document.getElementById('bar-feat').style.width = featPct + '%';
  document.getElementById('bar-none').style.width = nonePct + '%';
  document.getElementById('bar-enc').textContent = encPct >= 6 ? Math.round(encPct)+'%' : '';
  document.getElementById('bar-feat').textContent = featPct >= 6 ? Math.round(featPct)+'%' : '';
  document.getElementById('bar-none').textContent = nonePct >= 6 ? Math.round(nonePct)+'%' : '';

  document.getElementById('leg-enc').textContent = fmtFull(enc);
  document.getElementById('leg-feat').textContent = fmtFull(feat);
  document.getElementById('leg-none').textContent = fmtFull(none);
  document.getElementById('leg-enc-pct').textContent = '· ' + (provTotal ? pct(enc, provTotal) : '0%');
  document.getElementById('leg-feat-pct').textContent = '· ' + (provTotal ? pct(feat, provTotal) : '0%');
  document.getElementById('leg-none-pct').textContent = '· ' + (provTotal ? pct(none, provTotal) : '0%');

  // Per team: provider-level engagement; No BC = providers in practices with no BC
  const teams = {};
  for (const p of kpiSet){
    const tm = p.team || '— No team —';
    if (!teams[tm]) teams[tm] = { prac:0, enc:0, feat:0, none:0, noBc:0, prov:0 };
    teams[tm].prac++;
    for (const pr of (p.providers || [])){
      teams[tm].prov++;
      const e2 = provider30dEncFeatFromDaily(pr.provKey);
      const e = e2.enc, f = e2.feat;
      if (e > 0) teams[tm].enc++;
      else if (f > 0) teams[tm].feat++;
      else teams[tm].none++;
    }
    if (!p.bc) teams[tm].noBc += (p.providers || []).length;
  }
  const teamRows = Object.entries(teams)
    .sort((a,b) => b[1].prov - a[1].prov)
    .map(([name, s]) => {
      const tprov = s.enc + s.feat + s.none;
      const encShare = tprov ? pct(s.enc, tprov) : '0%';
      return `<tr>
        <td><strong>${escapeHtml(name)}</strong></td>
        <td>${fmtFull(s.prov)}</td>
        <td><span style="color:var(--brand-orange);font-weight:700">${fmtFull(s.enc)}</span></td>
        <td><span style="color:var(--brand-purple);font-weight:700">${fmtFull(s.feat)}</span></td>
        <td><span style="color:var(--slate-700)">${fmtFull(s.none)}</span></td>
        <td><strong>${encShare}</strong></td>
        <td>${s.noBc > 0 ? `<span class="badge b-no-bc">${s.noBc}</span>` : '—'}</td>
      </tr>`;
    }).join('');
  document.getElementById('team-rollup-tbody').innerHTML = teamRows
    || '<tr><td colspan="7" class="empty"><p>No clients in current filter</p></td></tr>';

  // PMA split — treating providers in each PMA (inherit practice PMA)
  let novaProv = 0, mpsProv = 0;
  for (const p of kpiSet){
    const n = (p.providers || []).length;
    if (p.pma === 'Nova') novaProv += n;
    else if (p.pma === 'myMPS') mpsProv += n;
  }
  const sumP = novaProv + mpsProv;
  const mpsPct = sumP ? (100*mpsProv/sumP) : 0;
  const novaPct = sumP ? (100*novaProv/sumP) : 0;

  document.getElementById('pma-mps').style.width = mpsPct + '%';
  document.getElementById('pma-nova').style.width = novaPct + '%';
  document.getElementById('pma-mps').textContent = mpsPct >= 8 ? `myMPS · ${Math.round(mpsPct)}%` : '';
  document.getElementById('pma-nova').textContent = novaPct >= 8 ? `Nova · ${Math.round(novaPct)}%` : '';
  document.getElementById('pma-mps-n').textContent = fmtFull(mpsProv);
  document.getElementById('pma-nova-n').textContent = fmtFull(novaProv);

  // Version — count treating providers (practice app version)
  const verCounts = {};
  for (const p of kpiSet){
    if (!p.appVer) continue;
    const w = (p.providers || []).length;
    if (!w) continue;
    verCounts[p.appVer] = (verCounts[p.appVer] || 0) + w;
  }
  const latest = (DATA.metadata.LatestVersion || '').trim();
  const verSorted = Object.entries(verCounts).sort((a,b) => b[1] - a[1]).slice(0, 6);
  const maxVerCount = verSorted.length ? verSorted[0][1] : 1;
  const verHtml = verSorted.map(([v,c]) => {
    const isLatest = v === latest;
    const w = (c / maxVerCount) * 100;
    return `<div style="display:flex;align-items:center;gap:10px;font-size:12px">
      <span style="font-family:var(--font-mono);font-weight:700;min-width:54px">${escapeHtml(v)}${isLatest ? ' <span style="color:var(--green-100)">★</span>' : ''}</span>
      <div style="flex:1;height:8px;background:var(--slate-100);border-radius:4px;overflow:hidden">
        <div style="height:100%;width:${w}%;background:${isLatest ? 'var(--green-100)' : 'var(--brand-orange)'};border-radius:4px"></div>
      </div>
      <span style="color:var(--slate-700);font-weight:700;min-width:36px;text-align:right">${fmtFull(c)}</span>
    </div>`;
  }).join('');
  document.getElementById('version-list').innerHTML = verHtml || '<div style="font-size:12px;color:var(--slate-700)">No version data</div>';

  // === Daily users chart ===
  killChart('daily-users');
  const ctx1 = document.getElementById('c-daily-users').getContext('2d');
  charts['daily-users'] = new Chart(ctx1, {
    type: 'line',
    data: {
      labels: dailyForSliceKpi().map(d => formatDateShort(d.d)),
      datasets: [
        { label: 'Encounter users', data: dailyForSliceKpi().map(d => d.encUsers),
          borderColor: getCss('--brand-orange'), backgroundColor: 'rgba(247,148,29,0.12)',
          tension: .35, fill: true, borderWidth: 2, pointRadius: 0, pointHoverRadius: 4 },
        { label: 'Feature-only users', data: dailyForSliceKpi().map(d => d.featUsers),
          borderColor: getCss('--brand-purple'), backgroundColor: 'rgba(119,87,236,0.10)',
          tension: .35, fill: true, borderWidth: 2, pointRadius: 0, pointHoverRadius: 4 },
      ]
    },
    options: chartLineOpts(),
  });

  // === Team bar chart ===
  killChart('team-bar');
  const ctx2 = document.getElementById('c-team-bar').getContext('2d');
  const teamArr = Object.entries(teams).sort((a,b) => b[1].prov - a[1].prov);
  charts['team-bar'] = new Chart(ctx2, {
    type: 'bar',
    data: {
      labels: teamArr.map(([t]) => t.replace(/Meraki\s*Outbound/i,'Meraki').replace(/^HB\s+/,'')),
      datasets: [
        { label: 'Encounter', data: teamArr.map(([,s]) => s.enc),
          backgroundColor: getCss('--brand-orange'), stack: 'a', borderRadius: 4 },
        { label: 'Feature-only', data: teamArr.map(([,s]) => s.feat),
          backgroundColor: getCss('--brand-purple'), stack: 'a', borderRadius: 4 },
        { label: 'No activity', data: teamArr.map(([,s]) => s.none),
          backgroundColor: getCss('--slate-300'), stack: 'a', borderRadius: 4 },
      ]
    },
    options: chartBarStackedOpts(),
  });

  // === Speciality split ===
  renderSpecialityChart(kpiSet);

  // === BC portfolio cards ===
  renderBCPortfolioCards(kpiSet);
}

function chartLineOpts(){
  return {
    responsive: true,
    maintainAspectRatio: false,
    interaction: { mode: 'index', intersect: false },
    plugins: {
      legend: { position: 'bottom', labels: { padding: 14 } },
    },
    scales: {
      x: { grid: { display: false }, ticks: { maxRotation: 0, autoSkip: true, maxTicksLimit: 12 } },
      y: { beginAtZero: true, grid: { color: 'rgba(0,0,0,.04)' }, ticks: { precision: 0 } },
    },
  };
}
function chartBarStackedOpts(){
  return {
    responsive: true, maintainAspectRatio: false,
    plugins: { legend: { position: 'bottom' } },
    scales: {
      x: { stacked: true, grid: { display: false }, ticks: { maxRotation: 35, minRotation: 0, font: { size: 10 } } },
      y: { stacked: true, beginAtZero: true, grid: { color: 'rgba(0,0,0,.04)' } },
    },
  };
}

/* Normalise speciality — merges GP variants but keeps Family Physician separate */
function normalizeSpeciality(s){
  if (!s) return 'Unknown';
  const t = s.trim().toLowerCase();
  if (t === 'family physician' || t === 'family medicine') return 'Family Physician';
  if (t === 'gp' || t === 'general practitioner' || t === 'general practice' ||
      t === 'general practice (gp)' || t === 'general pracitioner' || t === 'general pracioner') return 'GP';
  return s.trim();
}

/* Speciality stacked chart (custom) */
function renderSpecialityChart(set){
  const specs = {};
  for (const p of set){
    const s = normalizeSpeciality(p.speciality);
    for (const pr of (p.providers || [])){
      if (!specs[s]) specs[s] = { total: 0, enc: 0, feat: 0, none: 0, noBc: 0 };
      specs[s].total++;
      const e2s = provider30dEncFeatFromDaily(pr.provKey);
      const e = e2s.enc, f = e2s.feat;
      if (e > 0) specs[s].enc++;
      else if (f > 0) specs[s].feat++;
      else specs[s].none++;
      if (!p.bc) specs[s].noBc++;
    }
  }
  const arr = Object.entries(specs)
    .filter(([s]) => s !== 'Unknown')
    .sort((a, b) => b[1].total - a[1].total)
    .slice(0, 12);

  // Side-by-side: chart on the left, summary table on the right
  const summaryRows = arr.map(([s, st]) => `
    <tr>
      <td style="padding:4px 8px;font-size:12px">${escapeHtml(s)}</td>
      <td style="padding:4px 8px;text-align:right;font-weight:700;font-size:12px;font-variant-numeric:tabular-nums">${fmtFull(st.total)}</td>
      <td style="padding:4px 8px;text-align:right;font-size:12px;color:var(--brand-orange);font-weight:700">${pct(st.enc, st.total)}</td>
      <td style="padding:4px 8px;text-align:right;font-size:12px;color:${st.noBc > 0 ? 'var(--brand-burnt-orange)' : 'var(--slate-700)'};font-weight:${st.noBc > 0 ? '700' : '400'}">${st.noBc > 0 ? st.noBc : '\u2014'}</td>
    </tr>`).join('');

  const html = `
    <div style="display:grid;grid-template-columns:1.6fr 1fr;gap:24px;align-items:start">
      <div style="position:relative;height:${Math.max(280, arr.length * 32)}px">
        <canvas id="c-spec-bar"></canvas>
      </div>
      <div style="overflow:auto">
        <table style="width:100%;border-collapse:collapse">
          <thead>
            <tr>
              <th style="padding:6px 8px;text-align:left;font-size:10px;font-weight:800;color:var(--mu);text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid var(--bd)">Speciality</th>
              <th style="padding:6px 8px;text-align:right;font-size:10px;font-weight:800;color:var(--mu);text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid var(--bd)">Providers</th>
              <th style="padding:6px 8px;text-align:right;font-size:10px;font-weight:800;color:var(--mu);text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid var(--bd)">% Enc</th>
              <th style="padding:6px 8px;text-align:right;font-size:10px;font-weight:800;color:var(--mu);text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid var(--bd)">No BC</th>
            </tr>
          </thead>
          <tbody>${summaryRows}</tbody>
        </table>
      </div>
    </div>
  `;
  document.getElementById('spec-chart').innerHTML = html;

  killChart('spec-bar');
  const ctx = document.getElementById('c-spec-bar').getContext('2d');
  charts['spec-bar'] = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: arr.map(([s]) => s.length > 22 ? s.slice(0, 20) + '\u2026' : s),
      datasets: [
        { label: 'Encounter',    data: arr.map(([,s]) => s.enc),
          backgroundColor: getCss('--brand-orange'), stack: 'a', borderRadius: 4, borderSkipped: false },
        { label: 'Feature-only', data: arr.map(([,s]) => s.feat),
          backgroundColor: getCss('--brand-purple'), stack: 'a', borderRadius: 4, borderSkipped: false },
        { label: 'No activity',  data: arr.map(([,s]) => s.none),
          backgroundColor: getCss('--slate-300'),    stack: 'a', borderRadius: 4, borderSkipped: false },
      ]
    },
    options: {
      indexAxis: 'y',
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { padding: 12, font: { size: 11 } } },
        tooltip: {
          callbacks: {
            footer: (items) => {
              const i = items[0].dataIndex;
              const total = arr[i][1].total;
              const noBc  = arr[i][1].noBc;
              return 'Providers: ' + total + (noBc > 0 ? '  \u00b7  No BC (prov.): ' + noBc : '');
            }
          }
        }
      },
      scales: {
        x: { stacked: true, beginAtZero: true, grid: { color: 'rgba(0,0,0,.04)' }, ticks: { precision: 0 } },
        y: { stacked: true, grid: { display: false }, ticks: { font: { size: 11 } } },
      }
    }
  });
}

/* BC portfolio cards grouped by team (executive summary section) */
function renderBCPortfolioCards(set){
  // Group by team → bc → practices
  const byTeam = {};
  for (const p of set){
    const t = p.team || '— No team —';
    const b = p.bc || '— Unassigned —';
    byTeam[t] = byTeam[t] || {};
    byTeam[t][b] = byTeam[t][b] || [];
    byTeam[t][b].push(p);
  }
  const teamsSorted = Object.entries(byTeam).sort((a,b) => {
    const provs = (arr) => arr.reduce((n, p) => n + (p.providers || []).length, 0);
    const aN = provs(Object.values(a[1]).flat());
    const bN = provs(Object.values(b[1]).flat());
    return bN - aN;
  });

  const html = teamsSorted.map(([team, bcs]) => {
    const allP = Object.values(bcs).flat();
    const teamSp = providerEngagementSplit(allP);
    const teamTotal = allP.reduce((n, p) => n + (p.providers || []).length, 0);
    const teamEnc = teamSp.encProv;
    const teamNoBc = (bcs['— Unassigned —'] || []).reduce((n, p) => n + (p.providers || []).length, 0);

    const provCount = (ps) => ps.reduce((n, p) => n + (p.providers || []).length, 0);
    const bcCards = Object.entries(bcs).sort((a,b) => provCount(b[1]) - provCount(a[1])).map(([bc, prs]) => {
      const initials = bc === '— Unassigned —' ? '?' :
        bc.split(/\s+/).map(w => w[0]).join('').slice(0,2).toUpperCase();
      const sps = providerEngagementSplit(prs);
      const enc = sps.encProv;
      const feat = sps.featProv;
      const none = sps.noneProv;
      const totalEnc = prs.reduce((s, p) => s + p.enc, 0);
      const totalFeat = prs.reduce((s, p) => s + p.feat, 0);
      const isUnassigned = bc === '— Unassigned —';

      const rowsHtml = prs.sort((a,b) => b.enc - a.enc).map(p => `
        <tr>
          <td><strong>${escapeHtml(p.name)}</strong>${p.providerCount > 0 ? ` <span style="color:var(--slate-700);font-size:11px">· ${p.providerCount} prov.</span>` : ''}</td>
          <td><code style="font-size:11px;font-family:var(--font-mono);color:var(--slate-700)">${escapeHtml(p.bpn)}</code></td>
          <td>${pmaBadge(p.pma)}</td>
          <td>${versionChip(p.appVer, DATA.metadata.LatestVersion, p.onLatest)}</td>
          <td>${statusBadge(p.status)}</td>
          <td>${engagementBadge(p.engagement)}</td>
          <td style="text-align:right"><strong>${fmtFull(p.enc)}</strong></td>
          <td style="text-align:right">${fmtFull(p.feat)}</td>
          <td>${personaBadge(p.persona)}</td>
        </tr>`).join('');

      const cardId = `bc-${team}-${bc}`.replace(/[^a-z0-9]/gi,'_');
      return `
        <div class="bc-card"${isUnassigned ? ' style="border-color:var(--brand-burnt-orange);border-width:2px"' : ''}>
          <div class="bc-card-header" onclick="toggleBC('${cardId}')">
            <div class="bc-avatar"${isUnassigned ? ' style="background:var(--brand-burnt-orange)"' : ''}>${initials}</div>
            <div style="flex:1">
              <div class="bc-name">${escapeHtml(bc)}${isUnassigned ? ' <span class="badge b-no-bc" style="margin-left:6px">No BC assigned</span>' : ''}</div>
              <div class="bc-meta">${escapeHtml(team)} · ${prs.reduce((n, p) => n + (p.providers || []).length, 0)} treating provider${prs.reduce((n, p) => n + (p.providers || []).length, 0) === 1 ? '' : 's'}</div>
            </div>
            <div class="bc-stats">
              <div class="bc-stat"><div class="bc-stat-value bcs-orange">${enc}</div><div class="bc-stat-label">Enc</div></div>
              <div class="bc-stat"><div class="bc-stat-value bcs-purple">${feat}</div><div class="bc-stat-label">Feat</div></div>
              <div class="bc-stat"><div class="bc-stat-value" style="color:var(--slate-700)">${none}</div><div class="bc-stat-label">None</div></div>
              <div class="bc-stat"><div class="bc-stat-value bcs-mint">${fmt(totalEnc)}</div><div class="bc-stat-label">Total enc</div></div>
            </div>
            <span class="tog" id="tog-${cardId}">▼</span>
          </div>
          <div class="bc-card-body" id="body-${cardId}">
            <div class="table-wrap" style="margin-top:14px"><table>
              <thead><tr>
                <th>Practice</th><th>BPN</th><th>PMA</th><th>Version</th>
                <th>Status</th><th>Engagement</th>
                <th style="text-align:right">Encounters</th>
                <th style="text-align:right">Feature events</th>
                <th>Persona</th>
              </tr></thead>
              <tbody>${rowsHtml}</tbody>
            </table></div>
          </div>
        </div>`;
    }).join('');

    return `
      <div class="team-header">
        <h3>${escapeHtml(team)}</h3>
        <div class="team-stat"><strong>${teamTotal}</strong> treating provider${teamTotal === 1 ? '' : 's'}</div>
        <div class="team-stat"><strong>${teamEnc}</strong> encounter (prov.)</div>
        ${teamNoBc > 0 ? `<div class="team-stat" style="color:var(--brand-burnt-orange)"><strong>${teamNoBc}</strong> prov. unassigned</div>` : ''}
      </div>
      ${bcCards}`;
  }).join('');

  document.getElementById('exec-bc-list').innerHTML = html
    || '<div class="empty"><p>No BC portfolio data in current filter</p></div>';
}

function toggleBC(id){
  const body = document.getElementById('body-' + id);
  const tog = document.getElementById('tog-' + id);
  if (!body) return;
  body.classList.toggle('open');
  tog.classList.toggle('open');
}

/* ============================================================
   OVERVIEW
   ============================================================ */
function toggleDefs(){
  const panel = document.getElementById('defs-panel');
  const tog = document.getElementById('defs-toggle');
  if (panel.style.display === 'none'){
    panel.style.display = 'block';
    tog.innerHTML = '▼ Hide usage definitions';
  } else {
    panel.style.display = 'none';
    tog.innerHTML = '▶ Show usage definitions';
  }
}

function renderOverview(){
  applyChartDefaults();
  const set = FC;
  const kpiSet = fcForKpiStats();
  const totalEnc = kpiSet.reduce((s,p) => s + p.enc, 0);
  const totalAI = kpiSet.reduce((s,p) => s + (p.cats['5. AI Features']||0), 0);
  const kb = kpiBundleForFilteredPractices(kpiSet);

  document.getElementById('ov-kpi-prac').textContent = fmtFull(kb.pracN);
  document.getElementById('ov-kpi-prac-sub').textContent =
    FC.length === DATA.practices.length && kb.pracN === countEligiblePractices()
    ? 'all billing practices'
    : 'practices in filter';

  document.getElementById('ov-kpi-roster').textContent = fmtFull(kb.roster);
  document.getElementById('ov-kpi-roster-sub').textContent = 'active + inactive in filter';

  document.getElementById('ov-active').textContent = fmtFull(kb.activeProv);
  document.getElementById('ov-active-sub').textContent = getActiveProvidersKpiSubtitle();

  document.getElementById('ov-kpi-inactive').textContent = fmtFull(kb.noneProv);
  document.getElementById('ov-kpi-inactive-sub').textContent = kb.roster ? (pct(kb.noneProv, kb.roster) + ' of roster') : '—';

  document.getElementById('ov-kpi-favg').textContent = kb.activeProv
    ? (kb.featPerActive >= 10 ? kb.featPerActive.toFixed(1) : kb.featPerActive.toFixed(2))
    : '—';
  document.getElementById('ov-kpi-favg-sub').textContent = kb.activeProv ? 'mean · active providers only' : 'no active providers';

  document.getElementById('ov-enc').textContent = fmtFull(totalEnc);
  document.getElementById('ov-ai').textContent = fmtFull(totalAI);
  const daySpan = (SLICER && SLICER.dates && SLICER.dates.length)
    ? (SLICER.endIdx - SLICER.startIdx + 1)
    : 0;
  const avgEncPerDay = daySpan ? (totalEnc / daySpan) : 0;
  document.getElementById('ov-enc-pct').textContent = daySpan
    ? ((avgEncPerDay >= 100 ? fmt(Math.round(avgEncPerDay)) : avgEncPerDay.toFixed(1)) + ' avg consult-complete events/day in range')
    : '—';

  // Daily users chart (overview variant — uses same data)
  killChart('ov-daily');
  const ctx = document.getElementById('c-ov-daily').getContext('2d');
  charts['ov-daily'] = new Chart(ctx, {
    type: 'line',
    data: {
      labels: dailyForSliceKpi().map(d => formatDateShort(d.d)),
      datasets: [
        { label: 'Encounter users', data: dailyForSliceKpi().map(d => d.encUsers),
          borderColor: getCss('--brand-orange'), backgroundColor: 'rgba(247,148,29,0.12)',
          tension: .35, fill: true, borderWidth: 2, pointRadius: 0, pointHoverRadius: 4 },
        { label: 'Feature-only users', data: dailyForSliceKpi().map(d => d.featUsers),
          borderColor: getCss('--brand-purple'), backgroundColor: 'rgba(119,87,236,0.10)',
          tension: .35, fill: true, borderWidth: 2, pointRadius: 0, pointHoverRadius: 4 },
      ]
    },
    options: chartLineOpts(),
  });

  // Personas donut
  const pers = {};
  for (const p of kpiSet){
    pers[p.persona] = (pers[p.persona] || 0) + 1;
  }
  const personaKeys = ['Power Clinical User','Active Clinical User','Low Clinical User','Feature-Only User','Inactive','Dormant'];
  const personaColors = [getCss('--green-100'), getCss('--brand-orange'), getCss('--blue-100'), getCss('--brand-purple'), getCss('--brand-burnt-orange'), getCss('--slate-500')];
  killChart('personas');
  const ctx2 = document.getElementById('c-personas').getContext('2d');
  charts['personas'] = new Chart(ctx2, {
    type: 'doughnut',
    data: {
      labels: personaKeys,
      datasets: [{
        data: personaKeys.map(k => pers[k] || 0),
        backgroundColor: personaColors,
        borderColor: '#fff', borderWidth: 2,
      }]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      cutout: '65%',
      plugins: {
        legend: { position: 'right', labels: { boxWidth: 8, padding: 8, font: { size: 11 } } },
        tooltip: {
          callbacks: { label: (c) => `${c.label}: ${fmtFull(c.parsed)} (${pct(c.parsed, kpiSet.length)})` }
        }
      }
    }
  });

  // Top clients by encounters
  const top10 = [...kpiSet].filter(p => p.enc > 0).sort((a,b) => b.enc - a.enc).slice(0, 10);
  killChart('top-clients');
  const ctx3 = document.getElementById('c-top-clients').getContext('2d');
  charts['top-clients'] = new Chart(ctx3, {
    type: 'bar',
    data: {
      labels: top10.map(p => p.name.length > 24 ? p.name.slice(0,22)+'…' : p.name),
      datasets: [{
        label: 'Encounters',
        data: top10.map(p => p.enc),
        backgroundColor: getCss('--brand-orange'), borderRadius: 6,
      }]
    },
    options: {
      indexAxis: 'y',
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: {
        x: { beginAtZero: true, grid: { color: 'rgba(0,0,0,.04)' } },
        y: { grid: { display: false }, ticks: { font: { size: 11 } } },
      }
    }
  });

  // Category pie (meaningful events only)
  const catNames = ['1. Encounters','2. Clinical Doc','3. Scripts','4. Pathology','5. AI Features','6. Preventative Care','7. Task Management','8. Customization'];
  const catTotals = catNames.map(c => kpiSet.reduce((s,p) => s + (p.cats[c]||0), 0));
  const catColors = [
    getCss('--brand-orange'), getCss('--brand-purple'),
    getCss('--blue-100'), '#06b6d4',
    getCss('--brand-bright-green'), '#84cc16',
    '#f59e0b', getCss('--slate-700')
  ];
  killChart('cat-pie');
  const ctx4 = document.getElementById('c-cat-pie').getContext('2d');
  charts['cat-pie'] = new Chart(ctx4, {
    type: 'doughnut',
    data: {
      labels: catNames.map(c => c.replace(/^\d+\.\s*/,'')),
      datasets: [{ data: catTotals, backgroundColor: catColors, borderColor: '#fff', borderWidth: 2 }]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      cutout: '60%',
      plugins: {
        legend: { position: 'right', labels: { boxWidth: 8, padding: 6, font: { size: 11 } } },
        tooltip: {
          callbacks: {
            label: (c) => {
              const total = catTotals.reduce((a,b) => a+b, 0);
              return `${c.label}: ${fmtFull(c.parsed)} (${pct(c.parsed, total)})`;
            }
          }
        }
      }
    }
  });
}

/* ============================================================
   ENCOUNTERS
   ============================================================ */
function renderEncounters(){
  applyChartDefaults();
  const set = FC;
  const kpiSet = fcForKpiStats();
  const kb = kpiBundleForFilteredPractices(kpiSet);
  const totalEnc = kpiSet.reduce((s,p) => s + p.enc, 0);
  const encProvOnly = kb.encProv;
  const avgPerEncProv = encProvOnly ? (totalEnc / encProvOnly) : 0;

  document.getElementById('enc-kpi-prac').textContent = fmtFull(kb.pracN);
  document.getElementById('enc-kpi-prac-sub').textContent = 'billing practices · current filter';
  document.getElementById('enc-kpi-roster').textContent = fmtFull(kb.roster);
  document.getElementById('enc-kpi-roster-sub').textContent = 'active + inactive in filter';
  document.getElementById('enc-kpi-active').textContent = fmtFull(kb.activeProv);
  document.getElementById('enc-kpi-active-sub').textContent = getActiveProvidersKpiSubtitle();
  document.getElementById('enc-kpi-inactive').textContent = fmtFull(kb.noneProv);
  document.getElementById('enc-kpi-inactive-sub').textContent = kb.roster ? (pct(kb.noneProv, kb.roster) + ' of roster') : '—';
  document.getElementById('enc-kpi-favg').textContent = kb.activeProv
    ? (kb.featPerActive >= 10 ? kb.featPerActive.toFixed(1) : kb.featPerActive.toFixed(2))
    : '—';
  document.getElementById('enc-kpi-favg-sub').textContent = kb.activeProv ? 'mean · active providers only' : 'no active providers';

  document.getElementById('enc-k1').textContent = fmtFull(totalEnc);
  document.getElementById('enc-k2').textContent = avgPerEncProv.toFixed(1);

  // Daily encounter trend with 7-day MA
  killChart('enc-trend');
  const ctx = document.getElementById('c-encounter-trend').getContext('2d');
  const dailyEnc = dailyForSliceKpi().map(d => d.enc);
  // 7-day MA
  const ma = dailyEnc.map((_, i) => {
    const start = Math.max(0, i - 6);
    const slice = dailyEnc.slice(start, i + 1);
    return Math.round(slice.reduce((a,b) => a+b, 0) / slice.length);
  });
  charts['enc-trend'] = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: dailyForSliceKpi().map(d => formatDateShort(d.d)),
      datasets: [
        { type: 'bar', label: 'Daily encounters', data: dailyEnc,
          backgroundColor: 'rgba(247,148,29,0.4)', borderColor: getCss('--brand-orange'),
          borderWidth: 1, borderRadius: 2 },
        { type: 'line', label: '7-day moving avg', data: ma,
          borderColor: getCss('--brand-purple'), backgroundColor: 'transparent',
          tension: .35, borderWidth: 2.5, pointRadius: 0, pointHoverRadius: 4 },
      ]
    },
    options: chartLineOpts(),
  });

  renderEncTable();
}

function renderEncTable(){
  const teamFilter = document.getElementById('enc-team-filter').value;
  let set = FC;
  if (teamFilter) set = set.filter(p => p.team === teamFilter);
  const sorted = [...set].sort((a,b) => b.enc - a.enc).slice(0, 200);

  const rows = sorted.map((p, i) => {
    const { list: provListForPanel, shown: provShown, roster: provRoster } = providersForTablePanel(p);
    const provHtml = provListForPanel.map(pr => {
      const sl = providerStatsFromDaily(pr.provKey);
      const e = sl ? sl.enc : pr.enc;
      const f = sl ? sl.feat : pr.feat;
      const d = sl ? sl.days : pr.days;
      const la = sl ? sl.lastActive : pr.lastActive;
      return `
      <tr>
        <td><strong>${escapeHtml(pr.name)}</strong></td>
        <td><code style="font-size:11px;font-family:var(--font-mono)">${escapeHtml(pr.tpn)}</code></td>
        <td style="text-align:right"><strong>${fmtFull(e)}</strong></td>
        <td style="text-align:right">${fmtFull(f)}</td>
        <td>${d} day${d === 1 ? '' : 's'}</td>
        <td>${la ? formatDateShort(la) : '—'}</td>
        <td>${pr.appVer ? `<span class="badge ${pr.appVer === DATA.metadata.LatestVersion ? 'b-ver-ok' : 'b-ver-old'}">${escapeHtml(pr.appVer)}</span>` : '—'}</td>
        <td><button type="button" class="feat-btn" data-prov-key="${escapeHtmlAttr(pr.provKey)}" onclick="event.stopPropagation();openProviderFeaturesFromBtn(this)">📊 View features</button></td>
      </tr>
    `;
    }).join('');
    let provPanelHtml;
    if (!provRoster) {
      provPanelHtml = `<div class="prov-panel"><em style="color:var(--slate-700);font-size:12px">No per-provider detail in bundle</em></div>`;
    } else if (!provListForPanel.length) {
      const dm = DATA.metadata || {};
      provPanelHtml = `<div class="prov-panel"><em style="color:var(--slate-700);font-size:12px">No provider activity in the selected date range · ${provRoster} treating providers in the full bundle window (${dm.DataDateMin || '—'}–${dm.DataDateMax || '—'})</em></div>`;
    } else {
      let provTitle;
      if (!SLICER || !SLICER.dates || !SLICER.dates.length || (typeof slicerIsFullRange === 'function' && slicerIsFullRange())) {
        provTitle = `Treating providers (${provRoster})`;
      } else {
        provTitle = `Treating providers — ${provShown} with activity in selected range · ${provRoster} in full bundle`;
      }
      provPanelHtml = `
      <div class="prov-panel">
        <div class="prov-panel-title">${provTitle}</div>
        <div class="prov-table"><table>
          <thead><tr><th>Provider</th><th>TPN</th><th style="text-align:right">Enc</th><th style="text-align:right">Feat events</th><th>Days active</th><th>Last active</th><th>Version</th><th></th></tr></thead>
          <tbody>${provHtml}</tbody>
        </table></div>
      </div>`;
    }
    const rowId = 'er-' + i;
    return `
      <tr class="enc-row" onclick="toggleEncRow('${rowId}')" style="cursor:pointer">
        <td>${i+1}</td>
        <td><strong>${escapeHtml(p.name)}</strong></td>
        <td><code style="font-size:11px;font-family:var(--font-mono);color:var(--slate-700)">${escapeHtml(p.bpn)}</code></td>
        <td>${escapeHtml(p.bc) || '—'}</td>
        <td style="font-size:11px;color:var(--slate-700)">${escapeHtml(p.team) || '—'}</td>
        <td>${pmaBadge(p.pma)}</td>
        <td>${versionChip(p.appVer, DATA.metadata.LatestVersion, p.onLatest)}</td>
        <td>${personaBadge(p.persona)}</td>
        <td><strong>${fmtFull(p.enc)}</strong></td>
        <td>${encounterTableProviderCountHtml(p)}</td>
        <td>${statusBadge(p.status)}</td>
      </tr>
      <tr class="prov-detail-row" id="${rowId}" style="display:none">
        <td class="prov-detail-cell" colspan="11">${provPanelHtml}</td>
      </tr>`;
  }).join('');

  document.getElementById('enc-tbody').innerHTML = rows
    || '<tr><td colspan="11" class="empty"><p>No clients in current filter</p></td></tr>';
}

function toggleEncRow(id){
  const r = document.getElementById(id);
  if (!r) return;
  r.style.display = r.style.display === 'none' ? '' : 'none';
}

function escapeJs(s){
  return String(s||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
}

/* ============================================================
   FEATURES
   ============================================================ */
const FEAT_CATS = ['1. Encounters','2. Clinical Doc','3. Scripts','4. Pathology','5. AI Features','6. Preventative Care','7. Task Management','8. Customization'];
const FEAT_CAT_COLORS = {
  '1. Encounters': '#F7941D',
  '2. Clinical Doc': '#7757EC',
  '3. Scripts': '#0067C5',
  '4. Pathology': '#06b6d4',
  '5. AI Features': '#75EB9E',
  '6. Preventative Care': '#84cc16',
  '7. Task Management': '#f59e0b',
  '8. Customization': '#6D7175',
};

function renderFeatures(){
  applyChartDefaults();
  const set = FC;
  const kpiSet = fcForKpiStats();
  const kb = kpiBundleForFilteredPractices(kpiSet);
  document.getElementById('feat-kpi-prac').textContent = fmtFull(kb.pracN);
  document.getElementById('feat-kpi-prac-sub').textContent = 'billing practices · filter';
  document.getElementById('feat-kpi-roster').textContent = fmtFull(kb.roster);
  document.getElementById('feat-kpi-roster-sub').textContent = 'active + inactive in filter';
  document.getElementById('feat-kpi-active').textContent = fmtFull(kb.activeProv);
  document.getElementById('feat-kpi-active-sub').textContent = getActiveProvidersKpiSubtitle();
  document.getElementById('feat-kpi-inactive').textContent = fmtFull(kb.noneProv);
  document.getElementById('feat-kpi-inactive-sub').textContent = kb.roster ? (pct(kb.noneProv, kb.roster) + ' of roster') : '—';
  document.getElementById('feat-kpi-favg').textContent = kb.activeProv
    ? (kb.featPerActive >= 10 ? kb.featPerActive.toFixed(1) : kb.featPerActive.toFixed(2))
    : '—';
  document.getElementById('feat-kpi-favg-sub').textContent = kb.activeProv ? 'mean · active providers only' : 'no active providers';

  const totalMeaningful = kpiSet.reduce((s,p) => s + p.feat, 0);
  // Practice-level rollup (kept for context)
  const foClients = kpiSet.filter(p => p.engagement === 'feature_only').length;
  const fo = kb.featProv;
  const ai = kpiSet.reduce((s,p) => s + (p.cats['5. AI Features']||0), 0);

  // Top category
  const catTotals = {};
  for (const c of FEAT_CATS){
    catTotals[c] = kpiSet.reduce((s,p) => s + (p.cats[c]||0), 0);
  }
  const topCat = Object.entries(catTotals).sort((a,b) => b[1] - a[1])[0];

  document.getElementById('feat-k1').textContent = fmt(totalMeaningful);
  document.getElementById('feat-top-cat').textContent = topCat ? topCat[0].replace(/^\d+\.\s*/,'') : '—';
  document.getElementById('feat-top-sub').textContent = topCat ? `${pct(topCat[1], totalMeaningful)} of meaningful events` : '';
  document.getElementById('feat-ai-pct').textContent = pct(ai, totalMeaningful);
  document.getElementById('feat-fo').textContent = fmtFull(fo);
  var foSubEl = document.getElementById('feat-fo-sub');
  if (foSubEl) {
    foSubEl.textContent = 'treating providers · no consult-complete · same activity window · ' + fmtFull(foClients) + ' practices feature-only at practice level';
  }

  // Category pills (multi-select) + bulk-toggle controls
  const pillsEl = document.getElementById('feat-cat-pills');
  const allOn   = SELECTED_FEAT_CATS.length === FEAT_CATS.length;
  const noneOn  = SELECTED_FEAT_CATS.length === 0;
  const bulkBtns = `
    <button onclick="selectAllFeatCats()" ${allOn ? 'disabled' : ''}
      style="padding:6px 12px;border-radius:var(--r-pill);border:1.5px solid var(--slate-400);
             background:var(--white);color:var(--slate-700);
             font-family:inherit;font-size:11px;font-weight:700;cursor:${allOn ? 'not-allowed' : 'pointer'};
             opacity:${allOn ? '0.45' : '1'};transition:all 150ms"
      title="Show every category on the trend chart">Select all</button>
    <button onclick="clearFeatCats()" ${noneOn ? 'disabled' : ''}
      style="padding:6px 12px;border-radius:var(--r-pill);border:1.5px solid var(--slate-400);
             background:var(--white);color:var(--slate-700);
             font-family:inherit;font-size:11px;font-weight:700;cursor:${noneOn ? 'not-allowed' : 'pointer'};
             opacity:${noneOn ? '0.45' : '1'};transition:all 150ms"
      title="Hide every category from the trend chart">Deselect all</button>
    <span style="display:inline-block;width:1px;height:20px;background:var(--slate-300);margin:0 4px;align-self:center"></span>`;
  pillsEl.innerHTML = bulkBtns + FEAT_CATS.map(c => {
    const on = SELECTED_FEAT_CATS.includes(c);
    return `<button onclick="toggleFeatCat('${escapeJs(c)}')"
      style="padding:6px 12px;border-radius:var(--r-pill);border:1.5px solid ${on ? FEAT_CAT_COLORS[c] : 'var(--slate-300)'};
             background:${on ? FEAT_CAT_COLORS[c] : 'var(--white)'};color:${on ? '#fff' : 'var(--slate-700)'};
             font-family:inherit;font-size:11px;font-weight:700;cursor:pointer;transition:all 150ms">
      ${escapeHtml(c.replace(/^\d+\.\s*/,''))}
    </button>`;
  }).join('');

  // Stack chart
  killChart('feat-stack');
  const ctx = document.getElementById('c-feat-stack').getContext('2d');
  const datasets = SELECTED_FEAT_CATS.map(c => {
    const key = ({
      '1. Encounters':'evEnc','2. Clinical Doc':'evClin','3. Scripts':'evScripts',
      '4. Pathology':'evPath','5. AI Features':'evAI','6. Preventative Care':'evPrev',
      '7. Task Management':'evTask','8. Customization':'evCust'
    })[c];
    return {
      label: c.replace(/^\d+\.\s*/,''),
      data: dailyForSliceKpi().map(d => d[key] || 0),
      borderColor: FEAT_CAT_COLORS[c],
      backgroundColor: FEAT_CAT_COLORS[c] + '22',
      tension: .35, fill: false, borderWidth: 2,
      pointRadius: 0, pointHoverRadius: 4,
    };
  });
  charts['feat-stack'] = new Chart(ctx, {
    type: 'line',
    data: { labels: dailyForSliceKpi().map(d => formatDateShort(d.d)), datasets },
    options: chartLineOpts(),
  });

  // Category bars + drill
  renderFeatCatBars(kpiSet, totalMeaningful);
}

function toggleFeatCat(c){
  const i = SELECTED_FEAT_CATS.indexOf(c);
  if (i >= 0) SELECTED_FEAT_CATS.splice(i, 1);
  else SELECTED_FEAT_CATS.push(c);
  renderFeatures();
}

function selectAllFeatCats(){
  SELECTED_FEAT_CATS = [...FEAT_CATS];
  renderFeatures();
}

function clearFeatCats(){
  SELECTED_FEAT_CATS = [];
  renderFeatures();
}

function renderFeatCatBars(set, totalMeaningful){
  // For each category, sum all events across set, plus collect top features
  const catData = {};
  for (const c of FEAT_CATS){
    catData[c] = { total: 0, features: {} };
  }
  // Practice-level cat totals
  for (const p of set){
    for (const c of FEAT_CATS){
      catData[c].total += (p.cats[c] || 0);
    }
    // Top features now live on each provider (composite-key fix).
    // Aggregate across every provider in the practice so the drilldown
    // shows the real per-feature counts again.
    for (const prov of (p.providers || [])){
      for (const f of (prov.topFeatures || [])){
        const cat = f.category || f.cat;
        const featName = f.feature || f.name;
        if (cat in catData){
          catData[cat].features[featName] = (catData[cat].features[featName] || 0) + (f.count || 0);
        }
      }
    }
  }

  const html = FEAT_CATS.map((c, idx) => {
    const d = catData[c];
    const p = totalMeaningful ? (d.total / totalMeaningful) * 100 : 0;
    const featSorted = Object.entries(d.features).sort((a,b) => b[1] - a[1]).slice(0, 12);
    const maxF = featSorted.length ? featSorted[0][1] : 1;
    const featRows = featSorted.map(([fn, fc]) => {
      const w = (fc / maxF) * 100;
      return `<div class="feat-feat-row">
        <span class="feat-feat-name">${escapeHtml(featLabel(fn))}</span>
        <div class="feat-feat-bar-bg"><div class="feat-feat-bar-fill" style="width:${w}%;background:${FEAT_CAT_COLORS[c]}"></div></div>
        <span class="feat-feat-count">${fmt(fc)}</span>
      </div>`;
    }).join('');
    const cid = 'fc-' + idx;
    return `
      <div class="feat-cat-row" onclick="toggleFeatRow('${cid}')" id="row-${cid}">
        <span class="feat-cat-icon">▶</span>
        <span class="feat-cat-label">${escapeHtml(c.replace(/^\d+\.\s*/,''))}</span>
        <div class="feat-cat-track"><div class="feat-cat-fill" style="width:${p}%;background:${FEAT_CAT_COLORS[c]}"></div></div>
        <span class="feat-cat-pct">${pct1(d.total, totalMeaningful)}%</span>
        <span class="feat-cat-count">${fmt(d.total)}</span>
      </div>
      <div class="feat-features" id="${cid}">${featRows || '<div style="padding:10px 38px;color:var(--slate-700);font-size:12px">No features in window</div>'}</div>
    `;
  }).join('');
  document.getElementById('feat-cat-bars').innerHTML = html;
}

function toggleFeatRow(id){
  const body = document.getElementById(id);
  const row = document.getElementById('row-' + id);
  body.classList.toggle('open');
  row.classList.toggle('open');
}

/* ============================================================
   BC VIEW
   ============================================================ */
function renderBCView(){
  const kpiSet = fcForKpiStats();
  const kb = kpiBundleForFilteredPractices(kpiSet);
  let sumEnc = 0, sumFeat = 0;
  for (const p of kpiSet) {
    sumEnc += (p.enc || 0);
    sumFeat += (p.feat || 0);
  }
  const wExec = getExec30dWindow();
  const winLab = wExec.nDays
    ? (wExec.nDays >= 30 ? 'Up to 30d ending range' : (wExec.nDays + 'd ending range'))
    : '';
  const fullR = slicerIsFullRange();
  const dSpan = slicerDaySpan();
  const volSub = fullR
    ? 'KPI practices (test sites excluded) · full period in bundle'
    : ('KPI practices (test sites excluded) · selected ' + dSpan + 'd');

  function bcSetKpi(valId, subId, valText, subText){
    const v = document.getElementById(valId);
    if (v) v.textContent = valText;
    const s = document.getElementById(subId);
    if (s) s.textContent = subText;
  }
  bcSetKpi('bc-kpi-practices', 'bc-kpi-practices-sub', fmtFull(kb.pracN),
    FC.length === DATA.practices.length && kb.pracN === countEligiblePractices()
      ? 'eligible billing practices (test sites excluded from KPIs)'
      : 'practices in filter (test sites excluded from KPIs)');
  bcSetKpi('bc-kpi-roster', 'bc-kpi-roster-sub', fmtFull(kb.roster), 'active + inactive in filter');
  bcSetKpi('bc-kpi-active', 'bc-kpi-active-sub', fmtFull(kb.activeProv), getActiveProvidersKpiSubtitle());
  bcSetKpi('bc-kpi-inactive', 'bc-kpi-inactive-sub', fmtFull(kb.noneProv), winLab + ' · no activity');
  bcSetKpi('bc-kpi-favg', 'bc-kpi-favg-sub',
    kb.activeProv ? (kb.featPerActive >= 10 ? kb.featPerActive.toFixed(1) : kb.featPerActive.toFixed(2)) : '—',
    kb.activeProv ? 'mean · active providers only' : 'no active providers');
  bcSetKpi('bc-kpi-sum-enc', 'bc-kpi-sum-enc-sub', fmtFull(sumEnc), volSub);
  bcSetKpi('bc-kpi-sum-feat', 'bc-kpi-sum-feat-sub', fmtFull(sumFeat), volSub);

  const sorted = [...FC].sort((a,b) => {
    if (a.bc && !b.bc) return -1;
    if (!a.bc && b.bc) return 1;
    return b.enc - a.enc;
  }).slice(0, 250);

  const rows = sorted.map((p, i) => {
    const { list: provListForPanel, shown: provShown, roster: provRoster } = providersForTablePanel(p);
    const provHtml = provListForPanel.map(pr => {
      const sl = providerStatsFromDaily(pr.provKey);
      const e = sl ? sl.enc : pr.enc;
      const f = sl ? sl.feat : pr.feat;
      const d = sl ? sl.days : pr.days;
      const la = sl ? sl.lastActive : pr.lastActive;
      return `
      <tr>
        <td><strong>${escapeHtml(pr.name)}</strong></td>
        <td><code style="font-size:11px;font-family:var(--font-mono)">${escapeHtml(pr.tpn)}</code></td>
        <td style="text-align:right"><strong>${fmtFull(e)}</strong></td>
        <td style="text-align:right">${fmtFull(f)}</td>
        <td>${d} day${d === 1 ? '' : 's'}</td>
        <td>${la ? formatDateShort(la) : '—'}</td>
        <td>${pr.appVer ? `<span class="badge ${pr.appVer === DATA.metadata.LatestVersion ? 'b-ver-ok' : 'b-ver-old'}">${escapeHtml(pr.appVer)}</span>` : '—'}</td>
        <td><button type="button" class="feat-btn" data-prov-key="${escapeHtmlAttr(pr.provKey)}" onclick="event.stopPropagation();openProviderFeaturesFromBtn(this)">📊 View features</button></td>
      </tr>`;
    }).join('');
    let provPanelHtml;
    if (!provRoster) {
      provPanelHtml = `
      <div class="prov-panel">
        <em style="color:var(--slate-700);font-size:12px">No per-provider detail in bundle — practice-level events: ${fmtFull(p.feat)}</em>
      </div>`;
    } else if (!provListForPanel.length) {
      const dm = DATA.metadata || {};
      provPanelHtml = `
      <div class="prov-panel">
        <em style="color:var(--slate-700);font-size:12px">No provider activity in the selected date range · ${provRoster} treating providers in the full bundle (${dm.DataDateMin || '—'}–${dm.DataDateMax || '—'}) — practice-level events: ${fmtFull(p.feat)}</em>
      </div>`;
    } else {
      let provTitle;
      if (!SLICER || !SLICER.dates || !SLICER.dates.length || (typeof slicerIsFullRange === 'function' && slicerIsFullRange())) {
        provTitle = `${escapeHtml(p.name)} · ${provRoster} treating provider${provRoster === 1 ? '' : 's'} · click View features for per-provider breakdown`;
      } else {
        provTitle = `${escapeHtml(p.name)} · ${provShown} with activity in selected range · ${provRoster} in full bundle · click View features for breakdown`;
      }
      provPanelHtml = `
      <div class="prov-panel">
        <div class="prov-panel-title">${provTitle}</div>
        <div class="prov-table"><table>
          <thead><tr><th>Provider</th><th>TPN</th><th style="text-align:right">Enc</th><th style="text-align:right">Feat events</th><th>Days active</th><th>Last active</th><th>Version</th><th></th></tr></thead>
          <tbody>${provHtml}</tbody>
        </table></div>
      </div>`;
    }
    const rid = 'bv-' + i;
    return `
      <tr class="bc-row" onclick="toggleEncRow('${rid}')" style="cursor:pointer">
        <td><strong>${escapeHtml(p.name)}</strong></td>
        <td><code style="font-size:11px;font-family:var(--font-mono);color:var(--slate-700)">${escapeHtml(p.bpn)}</code></td>
        <td style="text-align:center">${bcViewProviderCountHtml(p)}</td>
        <td>${p.bc ? escapeHtml(p.bc) : '<span class="badge b-no-bc">No BC</span>'}</td>
        <td style="font-size:11px;color:var(--slate-700)">${escapeHtml(p.team) || '—'}</td>
        <td>${pmaBadge(p.pma)}</td>
        <td>${versionChip(p.appVer, DATA.metadata.LatestVersion, p.onLatest)}</td>
        <td>${statusBadge(p.status)}</td>
        <td>${engagementBadge(p.engagement)}</td>
        <td><strong>${fmtFull(p.enc)}</strong></td>
        <td>${fmt(p.feat)}</td>
        <td style="font-size:11px;color:var(--slate-700)">${p.lastActive ? formatDateShort(p.lastActive) : '—'}</td>
        <td>${personaBadge(p.persona)}</td>
      </tr>
      <tr class="prov-detail-row" id="${rid}" style="display:none">
        <td class="prov-detail-cell" colspan="13">${provPanelHtml}</td>
      </tr>`;
  }).join('');
  document.getElementById('bc-tbody').innerHTML = rows
    || '<tr><td colspan="13" class="empty"><p>No clients in current filter</p></td></tr>';
}

/* ============================================================
   ANOMALIES
   ============================================================ */
function renderAnomalies(){
  const counts = computeAnomCounts(fcForKpiStats());
  document.getElementById('anom-c1').textContent = counts.noBc;
  document.getElementById('anom-c2').textContent = counts.noEnc;
  document.getElementById('anom-c3').textContent = counts.oldVer;
  document.getElementById('anom-c4').textContent = counts.total;

  // Build anomaly list inline (so it respects filters)
  const meta = DATA.metadata;
  const list = [];
  for (const p of FC){
    if (!p.bc && (p.enc > 0 || p.feat > 0)){
      list.push({
        ...p, type: 'No BC assigned', sev: 'cr',
        detail: `${p.enc} enc · ${fmt(p.feat)} feat events with no owner`,
        action: 'Assign BC in 3C',
        topProvider: p.providers[0] ? p.providers[0].name : '—',
      });
    } else if (p.status === 'Active' && p.bc && p.enc === 0 && p.feat > 100){
      list.push({
        ...p, type: 'No encounters · feature-only', sev: 'wa',
        detail: `Logged in but zero consult-complete · ${fmt(p.feat)} feature events`,
        action: 'Investigate why provider not completing consults',
        topProvider: p.providers[0] ? p.providers[0].name : '—',
      });
    } else if (p.enc > 100 && p.appVer && !practiceMatchesLatestMeta(p)){
      list.push({
        ...p, type: 'Outdated app version', sev: 'in',
        detail: `On ${p.appVer} (latest: ${meta.LatestVersion || '6.47.1'})`,
        action: 'Schedule update',
        topProvider: p.providers[0] ? p.providers[0].name : '—',
      });
    }
  }
  const sevOrder = { cr:0, wa:1, in:2 };
  list.sort((a,b) => (sevOrder[a.sev]||3) - (sevOrder[b.sev]||3) || a.name.localeCompare(b.name));

  const rows = list.slice(0, 200).map(a => `
    <tr>
      <td><strong>${escapeHtml(a.name)}</strong></td>
      <td><code style="font-size:11px;font-family:var(--font-mono);color:var(--slate-700)">${escapeHtml(a.bpn)}</code></td>
      <td>${pmaBadge(a.pma)}</td>
      <td>${a.appVer ? versionChip(a.appVer, DATA.metadata.LatestVersion, a.onLatest) : '—'}</td>
      <td style="font-size:12px">${escapeHtml(a.topProvider)}</td>
      <td>${escapeHtml(a.bc) || '<span class="badge b-no-bc">—</span>'}</td>
      <td><strong>${escapeHtml(a.type)}</strong></td>
      <td>${severityBadge(a.sev)}</td>
      <td style="font-size:12px;color:var(--slate-700)">${escapeHtml(a.detail)}</td>
      <td style="font-size:12px">${escapeHtml(a.action)}</td>
    </tr>
  `).join('');
  document.getElementById('anom-tbody').innerHTML = rows
    || '<tr><td colspan="10" class="empty"><p>No anomalies in current filter</p><small>All clients are healthy ✓</small></td></tr>';
}

/* ============================================================
   PROVIDER FEATURE MODAL
   ============================================================ */
function openProviderFeatures(provKey){
  // provKey format: "{bpn}-{tpn}-{safe_pid}" generated by the Python script.
  // Parse bpn from the first segment to look up the practice.
  const bpnN = Number(provKey.split('-')[0]);
  const practice = DATA.practices.find(p => p.bpn === bpnN);
  if (!practice) { console.warn('openProviderFeatures: BPN not found', provKey); return; }
  const prov = (practice.providers || []).find(pr => pr.provKey === provKey);
  if (!prov) { console.warn('openProviderFeatures: provKey not found', provKey); return; }

  // Track which provider modal is open so the slicer can re-render it on change
  window._openModalKey = provKey;

  // ---- Slice-aware aggregation from provDaily ----
  // provDaily record: [di, enc, feat, evClin, evScripts, evPath, evAI, evPrev, evTask, evCust, evNoise]
  const sliceFull = (SLICER && SLICER.startIdx === 0 && SLICER.endIdx === SLICER.dates.length - 1);
  const provRecords = (DATA.provDaily && DATA.provDaily[provKey]) || [];
  let sEnc = 0, sFeat = 0, sNoise = 0, sDaysActive = 0, sLastIdx = -1;
  const sCats = {
    '1. Encounters': 0, '2. Clinical Doc': 0, '3. Scripts': 0, '4. Pathology': 0,
    '5. AI Features': 0, '6. Preventative Care': 0, '7. Task Management': 0,
    '8. Customization': 0, '9. Noise / Passive': 0
  };
  for (const r of provRecords){
    if (SLICER && (r[0] < SLICER.startIdx || r[0] > SLICER.endIdx)) continue;
    sEnc += r[1]; sFeat += r[2];
    sCats['1. Encounters'] += r[1];   // consult-complete count
    sCats['2. Clinical Doc'] += r[3];
    sCats['3. Scripts'] += r[4];
    sCats['4. Pathology'] += r[5];
    sCats['5. AI Features'] += r[6];
    sCats['6. Preventative Care'] += r[7];
    sCats['7. Task Management'] += r[8];
    sCats['8. Customization'] += r[9];
    sCats['9. Noise / Passive'] += r[10];
    sNoise += r[10];
    sDaysActive += 1;
    if (r[0] > sLastIdx) sLastIdx = r[0];
  }
  const sLastActive = sLastIdx >= 0 ? SLICER.dates[sLastIdx] : null;
  const sliceStartDate = SLICER ? SLICER.dates[SLICER.startIdx] : DATA.stats.dataPeriodStart;
  const sliceEndDate = SLICER ? SLICER.dates[SLICER.endIdx] : DATA.stats.dataPeriodEnd;

  // ---- Top features per category ----
  // Cumulative top-feature data exists at prov.topFeatures.
  // For sliced view, we scale each feature's count by the slice's share of that category's events.
  // This is an estimate (assumes feature mix within a category is roughly stable day to day).
  const topFeats = prov.topFeatures || [];
  const cumCatTotals = {};
  for (const f of topFeats){
    const cat = f.category || f.cat || 'Other';
    cumCatTotals[cat] = (cumCatTotals[cat] || 0) + (f.count || 0);
  }
  const byCat = {};
  for (const f of topFeats){
    const cat = f.category || f.cat || 'Other';
    const featName = f.feature || f.name || '';
    let count = f.count || 0;
    // Scale to slice
    if (!sliceFull && cumCatTotals[cat] > 0){
      const scale = (sCats[cat] || 0) / cumCatTotals[cat];
      count = Math.round(count * scale);
    }
    if (!byCat[cat]) byCat[cat] = [];
    byCat[cat].push({ category: cat, feature: featName, count });
  }
  // Drop features that scaled to 0 in the slice (no signal)
  for (const c of Object.keys(byCat)){
    byCat[c] = byCat[c].filter(f => f.count > 0);
    if (byCat[c].length === 0) delete byCat[c];
  }
  const cats = Object.keys(byCat).sort();
  const total = Object.values(sCats).reduce((s, v) => s + v, 0) - sCats['9. Noise / Passive'];

  const catBlocks = cats.map(c => {
    const feats = byCat[c].sort((a,b) => b.count - a.count);
    const max = feats[0].count || 1;
    const sumCat = sCats[c] || feats.reduce((s,f) => s + f.count, 0);
    const featRows = feats.map(f => {
      const w = (f.count / max) * 100;
      return `<div class="feat-feat-row" style="padding-left:18px">
        <span class="feat-feat-name">${escapeHtml(featLabel(f.feature))}</span>
        <div class="feat-feat-bar-bg"><div class="feat-feat-bar-fill" style="width:${w}%;background:${FEAT_CAT_COLORS[c] || '#999'}"></div></div>
        <span class="feat-feat-count">${fmt(f.count)}</span>
      </div>`;
    }).join('');
    return `
      <div style="padding:14px 24px 6px;border-bottom:1px solid var(--slate-300)">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
          <span style="display:inline-block;width:10px;height:10px;background:${FEAT_CAT_COLORS[c] || '#999'};border-radius:2px"></span>
          <strong style="font-size:13px">${escapeHtml(c.replace(/^\d+\.\s*/,''))}</strong>
          <span style="font-size:11px;color:var(--slate-700);margin-left:auto">${fmt(sumCat)} events · ${pct(sumCat, total)}</span>
        </div>
        ${featRows}
      </div>`;
  }).join('');

  const html = `
    <div class="modal-backdrop" onclick="if(event.target===this)closeProviderModal()">
      <div class="modal">
        <div class="modal-header">
          <div>
            <div class="modal-title">${escapeHtml(prov.name)}</div>
            <div class="modal-sub">
              ${escapeHtml(practice.name)} · BPN <code style="font-family:var(--font-mono)">${escapeHtml(practice.bpn)}</code> · TPN <code style="font-family:var(--font-mono)">${escapeHtml(prov.tpn)}</code>
            </div>
          </div>
          <button class="modal-close" onclick="closeProviderModal()">✕</button>
        </div>
        <div class="modal-meta">
          <span><strong style="color:var(--brand-orange)">${fmtFull(sEnc)}</strong> encounters</span>
          <span><strong style="color:var(--brand-purple)">${fmtFull(sFeat)}</strong> feature events</span>
          <span><strong>${sDaysActive}</strong> day${sDaysActive === 1 ? '' : 's'} active</span>
          <span>Last active: <strong>${sLastActive ? formatDate(sLastActive) : '—'}</strong></span>
          <span>Version: ${prov.appVer ? versionChip(prov.appVer, DATA.metadata.LatestVersion, prov.appVer === DATA.metadata.LatestVersion) : '—'}</span>
        </div>
        <div class="modal-body">
          ${catBlocks || '<div class="empty"><p>No feature events in selected window</p></div>'}
        </div>
        <div class="modal-footer">${sliceFull ? 'All-time top features' : 'Top features (scaled to slice)'} · window: ${formatDate(sliceStartDate)} → ${formatDate(sliceEndDate)}</div>
      </div>
    </div>`;

  const wrap = document.createElement('div');
  wrap.id = 'provider-modal';
  wrap.innerHTML = html;
  document.body.appendChild(wrap);
  document.body.style.overflow = 'hidden';
}

function closeProviderModal(){
  const m = document.getElementById('provider-modal');
  if (m) m.remove();
  document.body.style.overflow = '';
  window._openModalKey = null;
}
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') closeProviderModal();
});


/* ============================================================
   DATE SLICER — full timeline scrubber + presets + custom dates
   ============================================================ */
const SLICER = {
  startIdx: 0,
  endIdx: 0,
  preset: 'all',
  draggingHandle: null,
};

function slicerInit(){
  const dates = DATA.dates || (DATA.daily || []).map(d => d.date);
  if (!dates.length) return;
  SLICER.dates = dates;
  SLICER.endIdx = dates.length - 1;
  SLICER.startIdx = 0;
  slicerUpdateUI();
  slicerWireEvents();
}

function slicerWireEvents(){
  if (!document.getElementById('slicer-from')) return; // guard: slicer not in DOM yet
  // Presets
  document.querySelectorAll('.slicer-preset').forEach(btn => {
    btn.addEventListener('click', () => slicerApplyPreset(btn.dataset.preset));
  });

  // Date inputs
  document.getElementById('slicer-from').addEventListener('change', e => {
    const idx = SLICER.dates.indexOf(e.target.value);
    if (idx >= 0 && idx <= SLICER.endIdx){
      SLICER.startIdx = idx; SLICER.preset = 'custom';
      slicerUpdateUI(); slicerRenderAll();
    }
  });
  document.getElementById('slicer-to').addEventListener('change', e => {
    const idx = SLICER.dates.indexOf(e.target.value);
    if (idx >= 0 && idx >= SLICER.startIdx){
      SLICER.endIdx = idx; SLICER.preset = 'custom';
      slicerUpdateUI(); slicerRenderAll();
    }
  });

  // Drag handles
  ['left', 'right'].forEach(side => {
    const h = document.getElementById('slicer-handle-' + side);
    h.addEventListener('mousedown', e => slicerStartDrag(e, side));
    h.addEventListener('touchstart', e => slicerStartDrag(e.touches[0], side), {passive: true});
  });
  document.addEventListener('mousemove', slicerDrag);
  document.addEventListener('touchmove', e => slicerDrag(e.touches[0]), {passive: true});
  document.addEventListener('mouseup', slicerEndDrag);
  document.addEventListener('touchend', slicerEndDrag);

  // Click on track to set nearest handle
  document.getElementById('slicer-track').addEventListener('click', slicerClickTrack);
}

function slicerApplyPreset(preset){
  const n = SLICER.dates.length;
  const lastIdx = n - 1;
  const lastDate = new Date(SLICER.dates[lastIdx] + 'T00:00:00');
  let from = 0, to = lastIdx;
  switch(preset){
    case '7d':
    case '7':
      from = Math.max(0, lastIdx - 6);
      break;
    case '14d':
      from = Math.max(0, lastIdx - 13);
      break;
    case '30d':
    case '30':
      from = Math.max(0, lastIdx - 29);
      break;
    case '90d':
    case '90':
      from = Math.max(0, lastIdx - 89);
      break;
    case 'mtd':
      const mtdStart = new Date(lastDate.getFullYear(), lastDate.getMonth(), 1);
      from = SLICER.dates.findIndex(d => new Date(d + 'T00:00:00') >= mtdStart);
      if (from < 0) from = 0;
      break;
    case 'qtd':
      const qStartMonth = Math.floor(lastDate.getMonth() / 3) * 3;
      const qtdStart = new Date(lastDate.getFullYear(), qStartMonth, 1);
      from = SLICER.dates.findIndex(d => new Date(d + 'T00:00:00') >= qtdStart);
      if (from < 0) from = 0;
      break;
    case 'ytd':
      const ytdStart = new Date(lastDate.getFullYear(), 0, 1);
      from = SLICER.dates.findIndex(d => new Date(d + 'T00:00:00') >= ytdStart);
      if (from < 0) from = 0;
      break;
    case 'all':
    default:
      from = 0; to = lastIdx;
  }
  SLICER.startIdx = from;
  SLICER.endIdx = to;
  SLICER.preset = preset;
  slicerUpdateUI();
  slicerRenderAll();
}

function slicerStartDrag(evt, side){
  SLICER.draggingHandle = side;
  document.getElementById('slicer-handle-' + side).classList.add('dragging');
  evt.preventDefault && evt.preventDefault();
}

function slicerEndDrag(){
  if (SLICER.draggingHandle){
    document.getElementById('slicer-handle-' + SLICER.draggingHandle).classList.remove('dragging');
    SLICER.draggingHandle = null;
    slicerRenderAll();
  }
}

function slicerDrag(evt){
  if (!SLICER.draggingHandle) return;
  const track = document.getElementById('slicer-track');
  const rect = track.getBoundingClientRect();
  const x = (evt.clientX - rect.left) / rect.width;
  const n = SLICER.dates.length;
  const idx = Math.max(0, Math.min(n - 1, Math.round(x * (n - 1))));
  if (SLICER.draggingHandle === 'left'){
    SLICER.startIdx = Math.min(idx, SLICER.endIdx);
  } else {
    SLICER.endIdx = Math.max(idx, SLICER.startIdx);
  }
  SLICER.preset = 'custom';
  slicerUpdateUI();
}

function slicerClickTrack(evt){
  // Find nearest handle and move it
  if (evt.target.classList.contains('slicer-handle')) return;
  const track = document.getElementById('slicer-track');
  const rect = track.getBoundingClientRect();
  const x = (evt.clientX - rect.left) / rect.width;
  const n = SLICER.dates.length;
  const idx = Math.max(0, Math.min(n - 1, Math.round(x * (n - 1))));
  // Distance from each handle
  const dl = Math.abs(idx - SLICER.startIdx);
  const dr = Math.abs(idx - SLICER.endIdx);
  if (dl <= dr) SLICER.startIdx = Math.min(idx, SLICER.endIdx);
  else          SLICER.endIdx   = Math.max(idx, SLICER.startIdx);
  SLICER.preset = 'custom';
  slicerUpdateUI();
  slicerRenderAll();
}

function slicerUpdateUI(){
  if (!document.getElementById('slicer-handle-left')) return; // guard: slicer not in DOM yet
  const n = SLICER.dates.length;
  const startPct = (SLICER.startIdx / (n - 1)) * 100;
  const endPct = (SLICER.endIdx / (n - 1)) * 100;
  document.getElementById('slicer-handle-left').style.left = startPct + '%';
  document.getElementById('slicer-handle-right').style.left = endPct + '%';
  document.getElementById('slicer-fill').style.left = startPct + '%';
  document.getElementById('slicer-fill').style.width = (endPct - startPct) + '%';

  const startDate = SLICER.dates[SLICER.startIdx];
  const endDate = SLICER.dates[SLICER.endIdx];
  document.getElementById('slicer-tip-left').textContent = formatDateShort(startDate);
  document.getElementById('slicer-tip-right').textContent = formatDateShort(endDate);
  document.getElementById('slicer-from').value = startDate;
  document.getElementById('slicer-to').value = endDate;
  document.getElementById('slicer-from').min = SLICER.dates[0];
  document.getElementById('slicer-from').max = endDate;
  document.getElementById('slicer-to').min = startDate;
  document.getElementById('slicer-to').max = SLICER.dates[n-1];

  const days = SLICER.endIdx - SLICER.startIdx + 1;
  document.getElementById('slicer-summary').innerHTML =
    `<strong>${formatDateShort(startDate)}</strong> → <strong>${formatDateShort(endDate)}</strong> · <strong>${days}</strong> day${days===1?'':'s'}`;

  document.querySelectorAll('.slicer-preset').forEach(b => {
    b.classList.toggle('active', b.dataset.preset === SLICER.preset);
  });
}

/* ============================================================
   SLICED AGGREGATION — recompute practice totals from bpnDaily
   ============================================================ */
function aggregateForSlice(p){
  // If slice covers entire window, return the cumulative totals untouched
  const n = SLICER.dates.length;
  if (SLICER.startIdx === 0 && SLICER.endIdx === n - 1){
    return p;  // unchanged — most efficient path
  }
  const records = (DATA.bpnDaily && DATA.bpnDaily[String(p.bpn)]) || [];
  let enc = 0, feat = 0, evClin = 0, evScripts = 0, evPath = 0,
      evAI = 0, evPrev = 0, evTask = 0, evCust = 0, evNoise = 0,
      encUserDays = 0, featOnlyUserDays = 0, daysActive = 0,
      lastActiveIdx = -1;
  // Records: [dateIdx, enc, feat, evClin, evScripts, evPath, evAI, evPrev, evTask, evCust, evNoise, encUserDays, featOnlyUserDays]
  for (const r of records){
    if (r[0] < SLICER.startIdx || r[0] > SLICER.endIdx) continue;
    enc += r[1]; feat += r[2];
    evClin += r[3]; evScripts += r[4]; evPath += r[5]; evAI += r[6];
    evPrev += r[7]; evTask += r[8]; evCust += r[9]; evNoise += r[10];
    encUserDays += r[11]; featOnlyUserDays += r[12];
    daysActive += 1;
    if (r[0] > lastActiveIdx) lastActiveIdx = r[0];
  }
  const lastActive = lastActiveIdx >= 0 ? SLICER.dates[lastActiveIdx] : null;
  // Persona — recomputed for slice
  let persona;
  if (p.status !== 'Active' && p.status !== 'InProgress') persona = 'Inactive';
  else if (enc === 0 && feat === 0) persona = 'Dormant';
  else {
    const sliceLen = SLICER.endIdx - SLICER.startIdx + 1;
    const powerDays  = Math.round(sliceLen * (20 / 30));  // ≥20/30 days
    const activeDays = Math.round(sliceLen * (10 / 30));  // ≥10/30 days
    const lowDays    = Math.round(sliceLen * ( 5 / 30));  // ≥5/30 days
    if      (enc > 0 && daysActive >= powerDays)  persona = 'Power Clinical User';
    else if (enc > 0 && daysActive >= activeDays) persona = 'Active Clinical User';
    else if (enc > 0)                             persona = 'Low Clinical User';
    else if (feat > 0)                            persona = 'Feature-Only User';
    else                                          persona = 'Dormant';
  }
  let engagement;
  if (enc > 0) engagement = 'encounter';
  else if (feat > 0) engagement = 'feature_only';
  else engagement = 'inactive';

  return Object.assign({}, p, {
    totalEncounters: enc, enc: enc,
    totalMeaningfulEvents: feat, feat: feat,
    daysActive: daysActive,
    lastActiveDate: lastActive, lastActive: lastActive,
    encounterUserDays: encUserDays, encUserDays: encUserDays,
    featureOnlyUserDays: featOnlyUserDays,
    eventsClinicalDoc: evClin, eventsScripts: evScripts, eventsPathology: evPath,
    eventsAI: evAI, eventsPreventative: evPrev, eventsTaskManagement: evTask,
    eventsCustomization: evCust, eventsNoise: evNoise,
    eventsEncounters: enc,  // category total = consult-complete sum
    cats: {
      '1. Encounters': enc,
      '2. Clinical Doc': evClin,
      '3. Scripts': evScripts,
      '4. Pathology': evPath,
      '5. AI Features': evAI,
      '6. Preventative Care': evPrev,
      '7. Task Management': evTask,
      '8. Customization': evCust,
      '9. Noise / Passive': evNoise,
    },
    persona: persona,
    engagement: engagement,
  });
}

function aggregateAllForSlice(){
  return DATA.practices.map(aggregateForSlice);
}

function dailyForSlice(){
  return DATA.daily.slice(SLICER.startIdx, SLICER.endIdx + 1);
}

function slicerIsFullRange(){
  const n = SLICER && SLICER.dates && SLICER.dates.length;
  if (!n) return true;
  return SLICER.startIdx === 0 && SLICER.endIdx === n - 1;
}
function slicerDaySpan(){
  if (!SLICER || !SLICER.dates || !SLICER.dates.length) return 0;
  return SLICER.endIdx - SLICER.startIdx + 1;
}
/** Narrow slice: totals from provDaily. Full range: returns null — use cumulative pr.* from JSON. */
function providerStatsFromDaily(provKey){
  if (!SLICER || !SLICER.dates || !SLICER.dates.length) return null;
  if (slicerIsFullRange()) return null;
  const recs = (DATA.provDaily && provKey && DATA.provDaily[provKey]) || [];
  let enc = 0, feat = 0, days = 0, lastIdx = -1;
  for (const r of recs){
    if (r[0] < SLICER.startIdx || r[0] > SLICER.endIdx) continue;
    enc += r[1]; feat += r[2]; days += 1;
    if (r[0] > lastIdx) lastIdx = r[0];
  }
  return { enc, feat, days, lastActive: lastIdx >= 0 ? SLICER.dates[lastIdx] : null };
}
function updateSlicerDependentLabels(){
  if (!document.getElementById('bc-th-enc')) return;
  const full = slicerIsFullRange();
  const days = slicerDaySpan();
  const encH = full ? 'Enc (full)' : ('Enc (' + days + 'd)');
  const featH = full ? 'Feature events' : ('Feature events (' + days + 'd)');
  const el1 = document.getElementById('bc-th-enc');
  if (el1) el1.textContent = encH;
  const el2 = document.getElementById('enc-th-enc');
  if (el2) el2.textContent = encH;
  const el3 = document.getElementById('bc-th-feat');
  if (el3) el3.textContent = featH;
}


/* Re-render everything */
let _slicerRerenderTimer = null;
function slicerRenderAll(){
  // Debounce so dragging doesn't thrash
  clearTimeout(_slicerRerenderTimer);
  _slicerRerenderTimer = setTimeout(() => {
    if (typeof applyFilters === 'function') applyFilters();
    // Refresh provider modal if open
    if (window._openModalKey){
      const existing = document.getElementById('provider-modal');
      if (existing){
        existing.remove();
        document.body.style.overflow = '';
        if (typeof openProviderFeatures === 'function'){
          openProviderFeatures(window._openModalKey);
        }
      }
    }
  }, 80);
}


/* ============================================================
   DEFINITIONS TAB
   ============================================================ */
function renderDefs(){
  const el = document.getElementById('defs-content');
  if (!el) return;
  el.innerHTML = `
    <style>
      .def-section { margin-bottom: 28px; }
      .def-section-title {
        font-size: 13px; font-weight: 800; text-transform: uppercase;
        letter-spacing: .6px; color: var(--slate-700);
        margin-bottom: 12px; padding-bottom: 8px;
        border-bottom: 2px solid var(--slate-300);
      }
      .def-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 10px; }
      .def-card {
        background: var(--white); border-radius: var(--r-sm);
        border: 1.5px solid var(--slate-300); padding: 14px 16px;
        box-shadow: var(--sh-1);
      }
      .def-card-head { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
      .def-card-label { font-size: 13px; font-weight: 800; color: var(--slate-900); }
      .def-card-body { font-size: 12px; color: var(--slate-700); line-height: 1.55; }
      .def-card-body strong { color: var(--slate-900); }
      .def-rule { font-size: 11px; font-weight: 700; margin-top: 6px;
        padding: 4px 10px; border-radius: var(--r-pill);
        background: var(--slate-100); color: var(--slate-700);
        display: inline-block; }
      .def-swatch {
        width: 12px; height: 12px; border-radius: 3px; flex-shrink: 0;
      }
    </style>

    <!-- PERSONAS -->
    <div class="def-section">
      <div class="def-section-title">User Personas</div>
      <div class="def-grid">
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:var(--green-100)"></div>
            <span class="badge b-power def-card-label">Power Clinical User</span>
          </div>
          <div class="def-card-body">
            A highly engaged clinical user who consistently completes patient encounters.
            <span class="def-rule">Active ≥20 days in any 30-day period · must have completed encounters</span>
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:var(--brand-orange)"></div>
            <span class="badge b-standard def-card-label">Active Clinical User</span>
          </div>
          <div class="def-card-body">
            A regular clinical user completing encounters with moderate usage frequency.
            <span class="def-rule">Active ≥10 days in any 30-day period · must have completed encounters</span>
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:var(--slate-500)"></div>
            <span class="badge b-casual def-card-label">Low Clinical User</span>
          </div>
          <div class="def-card-body">
            A low-frequency clinical user who completes encounters but uses the platform infrequently.
            <span class="def-rule">Active ≥5 days in any 30-day period · must have completed encounters</span>
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:var(--brand-purple)"></div>
            <span class="badge b-admin def-card-label">Feature-Only User</span>
          </div>
          <div class="def-card-body">
            Uses the platform for features (scripts, referrals, tasks, etc.) and passive/noise events, but has <strong>zero completed encounters</strong>.
            <span class="def-rule">No consult-complete events · feature &amp; noise activity present</span>
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:var(--brand-burnt-orange)"></div>
            <span class="badge b-inactive-p def-card-label">Inactive / Dormant</span>
          </div>
          <div class="def-card-body">
            No events recorded in the selected date window, or contract status is not Active.
            <span class="def-rule">Zero events in window · or contract not Active</span>
          </div>
        </div>
      </div>
    </div>

    <!-- ENGAGEMENT TYPES -->
    <div class="def-section">
      <div class="def-section-title">Engagement Types</div>
      <div class="def-grid">
        <div class="def-card">
          <div class="def-card-head">
            <span class="badge b-eng-enc def-card-label">Encounter</span>
          </div>
          <div class="def-card-body">
            Practice has at least <strong>one consult-complete event</strong> in the selected date window. This is the primary signal of clinical platform adoption.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <span class="badge b-eng-feat def-card-label">Feature-only</span>
          </div>
          <div class="def-card-body">
            Practice has used platform features (scripts, pathology, tasks, AI tools, etc.) but has <strong>no consult-complete events</strong> in the window. Includes both meaningful and noise/passive events.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <span class="badge b-eng-inactive def-card-label">No activity</span>
          </div>
          <div class="def-card-body">
            <strong>Zero events</strong> of any type recorded in the selected date window. The practice may be onboarding, inactive, or churned.
          </div>
        </div>
      </div>
    </div>

    <!-- CONTRACT STATUSES -->
    <div class="def-section">
      <div class="def-section-title">Contract Statuses</div>
      <div class="def-grid">
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-active def-card-label">Active</span></div>
          <div class="def-card-body">Practice is live on the platform with a current, valid contract. Full access expected.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-progress def-card-label">In Progress</span></div>
          <div class="def-card-body">Onboarding or implementation is currently underway. Practice may have partial access.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-inactive def-card-label">Inactive</span></div>
          <div class="def-card-body">Practice is not currently active on the platform. May have been paused or lapsed.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-paused def-card-label">Paused</span></div>
          <div class="def-card-body">Practice is temporarily paused. Access may be restricted pending a decision or payment.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-paused def-card-label">On Hold</span></div>
          <div class="def-card-body">Contract or service is on hold, typically pending an internal or client action.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-cancel def-card-label">Cancelled</span></div>
          <div class="def-card-body">Contract or agreement has been formally cancelled. Practice should not be accessing the platform.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-cancel def-card-label">Pending Cancellation</span></div>
          <div class="def-card-body">Cancellation request has been submitted and is awaiting processing. Practice still has access.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-rejected def-card-label">Rejected</span></div>
          <div class="def-card-body">Application or onboarding request was rejected. Practice does not have platform access.</div>
        </div>
      </div>
    </div>

    <!-- PMA TYPES -->
    <div class="def-section">
      <div class="def-section-title">PMA (Practice Management Application)</div>
      <div class="def-grid">
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-pma-mps def-card-label">myMPS</span></div>
          <div class="def-card-body">
            Standard PMA platform. The legacy / established platform used by the majority of practices. Most common across the portfolio.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="badge b-pma-nova def-card-label">Nova</span></div>
          <div class="def-card-body">
            Modern cloud-based PMA platform. Newer architecture with enhanced integration capabilities. Practices migrating to Nova are tracked separately.
          </div>
        </div>
      </div>
    </div>

    <!-- FEATURE CATEGORIES -->
    <div class="def-section">
      <div class="def-section-title">Feature Categories</div>
      <div class="def-grid">
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:#F7941D"></div>
            <span class="def-card-label">1. Encounters</span>
          </div>
          <div class="def-card-body">
            Core clinical encounter events — primarily <strong>consult-complete</strong>, consult-started, and quick notes. The primary measure of clinical platform adoption.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:#7757EC"></div>
            <span class="def-card-label">2. Clinical Documentation</span>
          </div>
          <div class="def-card-body">
            Events related to clinical note-taking and documentation — talking points, encounter summaries, plan creation, ICD-10 coding.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:#0067C5"></div>
            <span class="def-card-label">3. Scripts</span>
          </div>
          <div class="def-card-body">
            Prescription and script-related actions — medicine search, generic selection, script saved and printed events.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:#06b6d4"></div>
            <span class="def-card-label">4. Pathology</span>
          </div>
          <div class="def-card-body">
            Pathology request workflow events — form opened, test selected, form submitted. Tracks lab request activity.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:#75EB9E"></div>
            <span class="def-card-label">5. AI Features</span>
          </div>
          <div class="def-card-body">
            Interactions with AI-powered tools — AI summary generation, Clinical Assistant opened, prompts submitted, suggestions accepted. Key indicator of advanced adoption.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:#84cc16"></div>
            <span class="def-card-label">6. Preventative Care</span>
          </div>
          <div class="def-card-body">
            Preventative health and wellness events — preventative care screenings and vaccination recording.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:#f59e0b"></div>
            <span class="def-card-label">7. Task Management</span>
          </div>
          <div class="def-card-body">
            Practice workflow and admin events — task creation and completion, reminder setting, appointment creation and check-in.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:#6D7175"></div>
            <span class="def-card-label">8. Customisation</span>
          </div>
          <div class="def-card-body">
            Platform personalisation events — preferences saved, sidebar usage. Indicates the provider is tailoring their workflow.
          </div>
        </div>
        <div class="def-card">
          <div class="def-card-head">
            <div class="def-swatch" style="background:var(--slate-300);border:1px solid var(--slate-500)"></div>
            <span class="def-card-label">9. Noise / Passive Events</span>
          </div>
          <div class="def-card-body">
            Passive or low-signal events — patient card opens, searches, sidebar opens. These indicate <strong>presence on the platform</strong> but not active feature use. Shown in Feature-Only user analysis.
          </div>
        </div>
      </div>
    </div>

    <!-- KEY METRICS -->
    <div class="def-section">
      <div class="def-section-title">Key Metrics &amp; Fields</div>
      <div class="def-grid">
        <div class="def-card">
          <div class="def-card-head"><span class="def-card-label">Encounters (enc)</span></div>
          <div class="def-card-body">Total number of <strong>consult-complete</strong> events in the selected date window. Primary measure of clinical usage.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="def-card-label">Feature Events</span></div>
          <div class="def-card-body">Total count of <strong>meaningful feature events</strong> across categories 2–8. Excludes noise/passive events unless viewing Feature-Only analysis.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="def-card-label">Days Active</span></div>
          <div class="def-card-body">Number of <strong>distinct calendar days</strong> on which any usage event was recorded. Used to calculate persona thresholds.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="def-card-label">BPN (Business Practice Number)</span></div>
          <div class="def-card-body">Unique identifier for a practice on the Healthbridge platform. Used to link all data to the correct organisation.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="def-card-label">TPN (Treating Provider Number)</span></div>
          <div class="def-card-body">Unique identifier for an individual treating provider (doctor/clinician). Multiple TPNs may exist under one BPN.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="def-card-label">BC (Business Consultant)</span></div>
          <div class="def-card-body">The Healthbridge BC assigned to support and grow this practice. A blank BC field flags the practice as unassigned and requires immediate action.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="def-card-label">App Version</span></div>
          <div class="def-card-body">The version of the Healthbridge clinical app currently installed at the practice. Shown as <span class="badge b-ver-ok">current ✓</span> (latest) or <span class="badge b-ver-old">outdated</span>.</div>
        </div>
        <div class="def-card">
          <div class="def-card-head"><span class="def-card-label">Last Active</span></div>
          <div class="def-card-body">The most recent date on which any event was recorded for this practice or provider in the dataset.</div>
        </div>
      </div>
    </div>

    <!-- ANOMALY TYPES -->
    <div class="def-section">
      <div class="def-section-title">Anomalies &amp; Alerts</div>
      <div class="def-grid">
        <div class="def-card" style="border-left: 4px solid var(--brand-burnt-orange)">
          <div class="def-card-head"><span class="badge b-sev-cr def-card-label">Critical — No BC Assigned</span></div>
          <div class="def-card-body">Practice has usage activity (encounters or features) but <strong>no BC is assigned</strong>. This client has no support owner and requires immediate action in 3C.</div>
        </div>
        <div class="def-card" style="border-left: 4px solid #f59e0b">
          <div class="def-card-head"><span class="badge b-sev-wa def-card-label">Warning — No Encounters</span></div>
          <div class="def-card-body">Practice has an Active status, a BC assigned, and feature activity (&gt;100 events), but <strong>zero completed encounters</strong>. Provider is logging in but not completing consults.</div>
        </div>
        <div class="def-card" style="border-left: 4px solid var(--brand-purple)">
          <div class="def-card-head"><span class="badge b-sev-in def-card-label">Info — Outdated App Version</span></div>
          <div class="def-card-body">Practice is actively using the platform (&gt;100 encounters) but is <strong>not on the latest app version</strong>. Schedule an update to ensure they receive the latest features and fixes.</div>
        </div>
      </div>
    </div>
  `;
}

/* ============================================================
   BOOT
   ============================================================ */
window.addEventListener('DOMContentLoaded', () => {
  applyChartDefaults();
  // Initialise date slicer first so applyFilters has SLICER context
  slicerInit();
  // Auto-login from session
  if (sessionStorage.getItem(SESSION_KEY) === '1'){
    enterApp();
  } else {
    document.getElementById('auth-pwd').focus();
  }
});

